export const ENGINE_FILES = {"upliftlab/__init__.py":"\"\"\"UpliftLab engine: an explore/exploit targeting loop with pluggable algorithms.\n\nThe same package runs in the browser (Pyodide) and natively (`python -m upliftlab serve`).\n\"\"\"\n__version__ = '0.23.0'\n","upliftlab/algorithms/__init__.py":"\"\"\"Built-in algorithms. Each file is a self-contained `class Model` that imports only common libraries (NumPy,\nscikit-learn), never upliftlab. The screen shows and runs these exact files.\"\"\"\nORDER = ['random_baseline', 'x_learner', 't_learner', 'r_learner', 'dml', 'duality_r_learner']\n","upliftlab/algorithms/dml.py":"\"\"\"Y와 T의 잔차를 cross-fitting으로 구하고, 그 관계로 CATE를 추정해요(Double Machine Learning). 비용은 보지 않아요.\n\nỹ = y − m̂(x)        t̃ = t − ê(x)        τ̂(x) = θ₀ + θ'x        θ = argmin Σ (ỹ − t̃·τ(x))²\nm̂와 ê는 3-fold cross-fitting으로 구해요. 모델은 context.base_learner에 따라 Ridge·로지스틱 회귀 또는 Gradient Boosting이에요(scikit-learn).\nR-Learner와 달리 propensity ê(x)도 추정해서, 처치가 공변량에 따라 달라지는 로그에서도 쓸 수 있어요.\n무작위 배정 데이터에서는 ê(x)가 상수에 가까워 R-Learner와 비슷한 결과가 나와요.\n\"\"\"\nimport numpy as np\nfrom sklearn.ensemble import HistGradientBoostingClassifier, HistGradientBoostingRegressor\nfrom sklearn.linear_model import LogisticRegression, Ridge\nfrom sklearn.model_selection import KFold, cross_val_predict\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nNAME = 'DML'\nFOLDS = 3\n\n\ndef outcome_model(kind):\n    if kind == 'tree':\n        return HistGradientBoostingRegressor(max_depth=3, max_iter=100, early_stopping=False, random_state=0)\n    return make_pipeline(StandardScaler(), Ridge(alpha=1.0))\n\n\ndef treatment_model(kind):\n    if kind == 'tree':\n        return HistGradientBoostingClassifier(max_depth=3, max_iter=100, early_stopping=False, random_state=0)\n    return make_pipeline(StandardScaler(), LogisticRegression(max_iter=1000))\n\n\ndef design(scaler, X):\n    return np.column_stack([np.ones(len(X)), scaler.transform(X)])\n\n\nclass Model:\n    def fit(self, train, validation, context):\n        kind = getattr(context, 'base_learner', 'ridge')\n        self.scaler = StandardScaler().fit(train.X)\n        self.finals = []\n        for arm in range(1, train.treatments + 1):\n            rows = (train.t == arm) | (train.t == 0)\n            X, y, t = train.X[rows], train.y[rows], (train.t[rows] == arm).astype(int)\n            folds = KFold(FOLDS, shuffle=True, random_state=context.model_seed)\n            y_res = y - cross_val_predict(outcome_model(kind), X, y, cv=folds)\n            t_res = t - np.clip(cross_val_predict(treatment_model(kind), X, t, cv=folds, method='predict_proba')[:, 1], .01, .99)\n            self.finals.append(Ridge(alpha=1.0, fit_intercept=False).fit(design(self.scaler, X) * t_res[:, None], y_res))\n\n    def predict(self, X):\n        Z = design(self.scaler, X)\n        return np.column_stack([final.predict(Z) for final in self.finals])\n","upliftlab/algorithms/duality_r_learner.py":"\"\"\"성과와 비용의 CATE를 R-Learner로 학습하고 τ̂ʳ − λ·τ̂ᶜ 순으로 정렬해요. λ는 validation AUCC가 가장 높은 값으로 정해요.\n\nscore = τ̂ʳ(x) − λ·τ̂ᶜ(x)        τ̂ʳ, τ̂ᶜ는 y / σ_y, cost / σ_c의 CATE예요.\nσ_y, σ_c는 train의 표준편차예요. 정규화하므로 성과와 비용의 단위가 바뀌어도 순위가 같아요.\n회귀 모델은 context.base_learner에 따라 Ridge 또는 Gradient Boosting이에요(scikit-learn).\n\"\"\"\nimport numpy as np\nfrom sklearn.ensemble import HistGradientBoostingRegressor\nfrom sklearn.linear_model import Ridge\nfrom sklearn.model_selection import KFold, cross_val_predict\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nNAME = 'Duality R-Learner'\nLAMBDAS = [0, 0.05, 0.1, 0.2, 0.4, 0.8, 1.6]  # 정규화한 성과와 비용 사이의 가중치\n\n\ndef base_model(kind):\n    if kind == 'tree':\n        return HistGradientBoostingRegressor(max_depth=3, max_iter=100, early_stopping=False, random_state=0)\n    return make_pipeline(StandardScaler(), Ridge(alpha=1.0))\n\n\ndef r_learner(X, t, y, propensity, seed, kind):\n    m = cross_val_predict(base_model(kind), X, y, cv=KFold(2, shuffle=True, random_state=seed))\n    w = t - propensity\n    weight = {'sample_weight': w ** 2} if kind == 'tree' else {'ridge__sample_weight': w ** 2}\n    return base_model(kind).fit(X, (y - m) / w, **weight)\n\n\ndef aucc(score, t, y, cost, points=20):\n    \"\"\"점수 순으로 상위 S를 골랐을 때 (증분 비용, 증분 성과) 곡선 아래 넓이를 0–1로 맞춘 값. 무작위 순서 ≈ 0.5.\"\"\"\n    order = np.argsort(-score, kind='stable')\n    cut = np.round(np.arange(1, points + 1) * len(order) / points).astype(int) - 1\n    T = (t[order] > 0).astype(float)\n    nT, nC = np.cumsum(T)[cut], np.cumsum(1 - T)[cut]\n    ok = (nT > 0) & (nC > 0)\n\n    def lift(v):\n        with np.errstate(divide='ignore', invalid='ignore'):\n            return np.where(ok, nT * (np.cumsum(v[order] * T)[cut] / nT - np.cumsum(v[order] * (1 - T))[cut] / nC), 0.)\n    gain, spend = np.r_[0., lift(y)], np.r_[0., lift(cost)]\n    if gain.max() <= 0 or spend.max() <= 0:\n        return None\n    x, h = spend / spend.max(), gain / gain.max()\n    return float(np.sum(np.diff(x) * (h[1:] + h[:-1]) / 2))\n\n\nclass Model:\n    score_is_effect = False  # 점수에 비용이 이미 들어 있어서 효과로 읽지 않아요. Knapsack과 효율 제약 선정에서 이 순서를 그대로 써요.\n\n    def fit(self, train, validation, context):\n        kind = getattr(context, 'base_learner', 'ridge')\n        y, cost = train.y / (train.y.std() or 1), train.cost / (train.cost.std() or 1)\n        self.arms = []\n        for arm in range(1, train.treatments + 1):\n            rows = (train.t == arm) | (train.t == 0)\n            t = (train.t[rows] == arm).astype(float)\n            e = train.propensities[arm - 1]\n            self.arms.append((r_learner(train.X[rows], t, y[rows], e, context.model_seed, kind), r_learner(train.X[rows], t, cost[rows], e, context.model_seed, kind)))\n        best = None\n        for i, lam in enumerate(LAMBDAS):\n            values = []\n            for arm, (gain, spend) in enumerate(self.arms, 1):\n                rows = (validation.t == arm) | (validation.t == 0)\n                values.append(aucc(gain.predict(validation.X[rows]) - lam * spend.predict(validation.X[rows]), validation.t[rows], validation.y[rows], validation.cost[rows]))\n            values = [v for v in values if v is not None]\n            val = float(np.mean(values)) if values else None\n            context.report(step=i + 1, total=len(LAMBDAS), lam=lam, val=val if val is not None else 0)\n            if best is None or (val is not None and (best[0] is None or val > best[0])):\n                best = (val, lam)\n        self.lam = best[1]\n\n    def predict(self, X):\n        return np.column_stack([gain.predict(X) - self.lam * spend.predict(X) for gain, spend in self.arms])\n","upliftlab/algorithms/r_learner.py":"\"\"\"결과와 처치의 잔차로 CATE를 학습해요(R-Learner). 비용은 보지 않아요.\n\ny − m(x) = (t − e)·τ(x) + ε\nm(x)는 2-fold cross-fitting으로 구하고, e는 propensity(상수)예요. τ(x)는 목표 (y − m) / (t − e), 가중치 (t − e)²인 회귀로 풀어요.\n회귀 모델은 context.base_learner에 따라 Ridge 또는 Gradient Boosting이에요(scikit-learn).\n\"\"\"\nimport numpy as np\nfrom sklearn.ensemble import HistGradientBoostingRegressor\nfrom sklearn.linear_model import Ridge\nfrom sklearn.model_selection import KFold, cross_val_predict\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nNAME = 'R-Learner'\n\n\ndef base_model(kind):\n    if kind == 'tree':\n        return HistGradientBoostingRegressor(max_depth=3, max_iter=100, early_stopping=False, random_state=0)\n    return make_pipeline(StandardScaler(), Ridge(alpha=1.0))\n\n\ndef r_learner(X, t, y, propensity, seed, kind):\n    \"\"\"τ(x)를 예측하는 모델을 반환해요.\"\"\"\n    m = cross_val_predict(base_model(kind), X, y, cv=KFold(2, shuffle=True, random_state=seed))\n    w = t - propensity\n    weight = {'sample_weight': w ** 2} if kind == 'tree' else {'ridge__sample_weight': w ** 2}\n    return base_model(kind).fit(X, (y - m) / w, **weight)\n\n\nclass Model:\n    def fit(self, train, validation, context):\n        kind = getattr(context, 'base_learner', 'ridge')\n        self.taus = []\n        for arm in range(1, train.treatments + 1):\n            rows = (train.t == arm) | (train.t == 0)\n            self.taus.append(r_learner(train.X[rows], (train.t[rows] == arm).astype(float), train.y[rows], train.propensities[arm - 1], context.model_seed, kind))\n\n    def predict(self, X):\n        return np.column_stack([tau.predict(X) for tau in self.taus])\n","upliftlab/algorithms/random_baseline.py":"\"\"\"무작위 점수로 정렬해요. 비교 기준선(baseline)이고, Cost Curve는 대각선에 가까워요.\"\"\"\nimport numpy as np\n\nNAME = 'Random'\n\n\nclass Model:\n    score_is_effect = False  # 점수가 무작위라서 효과로 읽지 않아요. Knapsack과 효율 제약 선정에서 이 순서를 그대로 써요.\n\n    def fit(self, train, validation, context):\n        self.rng = np.random.default_rng(context.seed)\n        self.treatments = train.treatments\n\n    def predict(self, X):\n        return self.rng.random((len(X), self.treatments))\n","upliftlab/algorithms/t_learner.py":"\"\"\"처치군과 대조군에 결과 모델을 따로 학습하고, 두 예측의 차이를 CATE로 써요(T-Learner). 비용은 보지 않아요.\n\nτ̂ₖ(x) = μ̂ₖ(x) − μ̂₀(x)        처치가 여러 종류면 처치마다 계산하고, 점수가 가장 큰 처치를 골라요.\nμ̂는 context.base_learner에 따라 Ridge 또는 Gradient Boosting이에요(scikit-learn).\n\"\"\"\nimport numpy as np\nfrom sklearn.ensemble import HistGradientBoostingRegressor\nfrom sklearn.linear_model import Ridge\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nNAME = 'T-Learner'\n\n\ndef base_model(kind):\n    if kind == 'tree':\n        return HistGradientBoostingRegressor(max_depth=3, max_iter=100, early_stopping=False, random_state=0)\n    return make_pipeline(StandardScaler(), Ridge(alpha=1.0))\n\n\nclass Model:\n    def fit(self, train, validation, context):\n        kind = getattr(context, 'base_learner', 'ridge')\n        control = train.t == 0\n        self.mu0 = base_model(kind).fit(train.X[control], train.y[control])\n        self.mu = [base_model(kind).fit(train.X[train.t == arm], train.y[train.t == arm]) for arm in range(1, train.treatments + 1)]\n\n    def predict(self, X):\n        base = self.mu0.predict(X)\n        return np.column_stack([mu.predict(X) - base for mu in self.mu])\n","upliftlab/algorithms/x_learner.py":"\"\"\"처치군과 대조군의 결과 모델로 사용자별 처치 효과를 대체(impute)하고, 두 효과 모델을 propensity로 가중 평균해요(X-Learner). 비용은 보지 않아요.\n\nDᵀ = y − μ̂₀(x)  (처치군)        Dᶜ = μ̂₁(x) − y  (대조군)\nτ̂(x) = e·τ̂ᶜ(x) + (1 − e)·τ̂ᵀ(x)\nμ̂와 τ̂는 context.base_learner에 따라 Ridge 또는 Gradient Boosting이고(scikit-learn), e는 propensity예요.\nRidge에서는 T-Learner와 거의 같은 점수가 나와요. 두 방법의 차이는 비선형 모델과 처치 비율이 불균형할 때 커져요.\n\"\"\"\nimport numpy as np\nfrom sklearn.ensemble import HistGradientBoostingRegressor\nfrom sklearn.linear_model import Ridge\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nNAME = 'X-Learner'\n\n\ndef base_model(kind):\n    if kind == 'tree':\n        return HistGradientBoostingRegressor(max_depth=3, max_iter=100, early_stopping=False, random_state=0)\n    return make_pipeline(StandardScaler(), Ridge(alpha=1.0))\n\n\nclass Model:\n    def fit(self, train, validation, context):\n        kind = getattr(context, 'base_learner', 'ridge')\n        control = train.t == 0\n        X0, y0 = train.X[control], train.y[control]\n        mu0 = base_model(kind).fit(X0, y0)\n        self.arms = []\n        for arm in range(1, train.treatments + 1):\n            treated = train.t == arm\n            X1, y1 = train.X[treated], train.y[treated]\n            mu1 = base_model(kind).fit(X1, y1)\n            tau1 = base_model(kind).fit(X1, y1 - mu0.predict(X1))\n            tau0 = base_model(kind).fit(X0, mu1.predict(X0) - y0)\n            self.arms.append((tau1, tau0, float(train.propensities[arm - 1])))\n\n    def predict(self, X):\n        return np.column_stack([e * tau0.predict(X) + (1 - e) * tau1.predict(X) for tau1, tau0, e in self.arms])\n","upliftlab/arena.py":"\"\"\"Head-to-head runs: every algorithm runs the same production loop on the same users.\n\nEach cycle a random explore share of the candidates is split into treatment and control. It is identical for every\nalgorithm: it is the training data and the baseline. Each algorithm's deployed model ranks the remaining candidates, and a\nselection rule turns that into its exploit group (see select()). That group is split into treatment and control again so\nthe online effect can be measured. After the cycle every algorithm retrains on the recent explore window and its new model\nserves the next cycle. Cycle 1 has no model yet, so every algorithm starts from the same random selection.\n\"\"\"\nimport time\n\nimport numpy as np\n\nfrom . import contract\nfrom .metrics import aucc, cell, cost_curve, qini, uplift_at\nfrom .scenario import SyntheticScenario, seed_of\n\nDRAWS = 200\nTRACE_SAMPLE, TRACE_TOP, TRACE_FEATURES = 100, 8, 20  # rows kept per cycle for the row table: a random sample plus each algorithm's top ranks\nMODES = ('quantile', 'budget', 'knapsack', 'roi', 'validation')\nBUDGET_MODES = ('budget', 'knapsack')\nBASE_LEARNERS = ('ridge', 'tree')\n\n\ndef boot(t, yr, yc, seed, draws=DRAWS):\n    \"\"\"Bootstrap draws of (ATEʳ, ATEᶜ), resampling treatment and control separately.\"\"\"\n    rng, means = np.random.default_rng(seed), []\n    for mask in (t > 0, t == 0):\n        r, c = yr[mask], yc[mask]\n        if not len(r):\n            return None\n        i = rng.integers(0, len(r), (draws, len(r)))\n        means.append((r[i].mean(1), c[i].mean(1)))\n    (rt, ct), (rc, cc) = means\n    return rt - rc, ct - cc\n\n\ndef interval(values):\n    v = np.sort(values[np.isfinite(values)])\n    return [float(v[int(len(v) * .025)]), float(v[max(0, int(np.ceil(len(v) * .975)) - 1)])] if len(v) > 10 else [None, None]\n\n\ndef relative(top, base):\n    with np.errstate(divide='ignore', invalid='ignore'):\n        return top / base - 1\n\n\ndef ratio_of(draws):\n    \"\"\"Bootstrap draws of cost effectiveness. A very small group can have no cost difference in a draw; interval() skips those.\"\"\"\n    with np.errstate(divide='ignore', invalid='ignore'):\n        return draws[0] / draws[1]\n\n\ndef splits(log, scenario):\n    cat = {k: np.concatenate([b[k] for b in log]) for k in ('X', 't', 'y', 'cost', 'split')}\n    masks = {'train': cat['split'] < .6, 'validation': (cat['split'] >= .6) & (cat['split'] < .8), 'test': cat['split'] >= .8}\n    sets = {k: contract.dataset(cat['X'][m], cat['t'][m], cat['y'][m], cat['cost'][m], scenario.propensity, scenario.features, scenario.treatments, scenario.propensities) for k, m in masks.items()}\n    if log[0]['tau_r'] is not None:\n        tau_r, tau_c = np.concatenate([b['tau_r'] for b in log]), np.concatenate([b['tau_c'] for b in log])\n        sets['test'].tau_r, sets['test'].tau_c = tau_r[masks['test']], tau_c[masks['test']]\n    return sets\n\n\ndef _policy(model, data):\n    \"\"\"Scores with the treatment each row would get. Only rows logged as control or as that treatment can be measured.\"\"\"\n    score, _, arm = contract.scores(model, data.X, data.treatments)\n    return score, arm, (data.t == 0) | (data.t == arm)\n\n\ndef _truth_of(tau, arm):\n    return tau if tau.ndim == 1 else tau[np.arange(len(tau)), arm - 1]\n\n\ndef evaluate(model, test, target):\n    score, arm, keep = _policy(model, test)\n    curve = cost_curve(score[keep], test.t[keep], test.y[keep], test.cost[keep])\n    out = {'n': int(keep.sum()), 'curve': curve, 'aucc': aucc(curve), 'qini': qini(curve), 'upliftAt': uplift_at(score[keep], target, test.t[keep], test.y[keep]), 'upliftK': target,\n           'truthCurve': None, 'auccTruth': None, 'qiniTruth': None, 'upliftAtTruth': None}\n    if hasattr(test, 'tau_r'):\n        tau_r, tau_c = _truth_of(test.tau_r, arm), _truth_of(test.tau_c, arm)\n        truth = cost_curve(score, None, None, None, tau_r=tau_r, tau_c=tau_c)\n        out.update(truthCurve=truth, auccTruth=aucc(truth), qiniTruth=qini(truth), upliftAtTruth=uplift_at(score, target, tau_r=tau_r))\n    return out\n\n\ndef fit(algorithm, sets, seed, cycle, target, device, report, base_learner='ridge'):\n    model_type, meta = contract.load(algorithm['code'], f\"{algorithm['id']}.py\")\n    s = seed_of(seed, 'fit', cycle)\n    ctx = contract.Context(seed=s, model_seed=s % 2 ** 31, device=device, target_fraction=target, cycle=cycle, segment='all', base_learner=base_learner, treatments=sets['train'].treatments,\n                           _emit=lambda m: report({'cycle': cycle, 'arm': algorithm['id'], 'phase': 'train', **m}))\n    np.random.seed(ctx.model_seed)\n    model = contract.instantiate(model_type)\n    started = time.perf_counter()\n    contract.fit(model, sets['train'], sets['validation'], ctx)\n    ms = (time.perf_counter() - started) * 1000\n    v = sets['validation']\n    score, _, keep = _policy(model, v)\n    val = aucc(cost_curve(score[keep], v.t[keep], v.y[keep], v.cost[keep]))\n    return model, {'ms': ms, 'val': val, 'name': meta['name']}\n\n\ndef _ridge(X, y, alpha=1.):\n    if len(y) <= X.shape[1]:  # a treatment with almost no rows in the window: fall back to its average\n        level = float(y.mean()) if len(y) else 0.\n        return lambda A: np.full(len(A), level)\n    mean, std = X.mean(0), X.std(0) + 1e-9\n    Z = (X - mean) / std\n    coef = np.linalg.solve(Z.T @ Z + alpha * np.eye(X.shape[1]), Z.T @ (y - y.mean()))\n    return lambda A: y.mean() + ((A - mean) / std) @ coef\n\n\ndef _difference_from_control(log, treatments, field):\n    cat = {k: np.concatenate([b[k] for b in log]) for k in ('X', 't', field, 'split')}\n    train = cat['split'] < .6\n    X, t, value = cat['X'][train], cat['t'][train], cat[field][train]\n    control = _ridge(X[t == 0], value[t == 0])\n    arms = [_ridge(X[t == k], value[t == k]) for k in range(1, treatments + 1)]\n    return lambda A: np.column_stack([arm(A) - control(A) for arm in arms])\n\n\ndef cost_estimator(log, treatments):\n    \"\"\"Expected incremental cost per user and treatment, learned from the shared Explore train rows.\n\n    Every algorithm is held to the same estimate, so a budget constrains them all the same way.\n    \"\"\"\n    difference = _difference_from_control(log, treatments, 'cost')\n\n    def estimate(A):\n        out = difference(A)\n        return np.maximum(out, max(1e-3 * float(np.abs(out).mean()), 1e-12))\n    return estimate\n\n\ndef gain_estimator(log, treatments):\n    \"\"\"Expected incremental outcome per user and treatment. It holds every algorithm to the same efficiency estimate, as cost_estimator does.\"\"\"\n    return _difference_from_control(log, treatments, 'y')\n\n\ndef knapsack(value, cost, budget):\n    \"\"\"The multiple-choice knapsack through its Lagrangian dual.\n\n    At price λ each user takes the treatment with the largest value − λ·cost, or none if that is not positive. Bisection finds\n    the lowest price the budget can pay for. With one treatment this is the greedy order of value / cost. Returns the treatment\n    index per user and that user's value − λ·cost.\n    \"\"\"\n    rows = np.arange(len(value))\n\n    def spend(price):\n        net = value - price * cost\n        best = net.argmax(1)\n        return float(cost[rows, best][net[rows, best] > 0].sum())\n    price = 0.\n    if spend(0.) > budget:\n        ratio = value / cost\n        low, price = 0., float(ratio[np.isfinite(ratio)].max())\n        for _ in range(60):\n            middle = (low + price) / 2\n            if spend(middle) > budget:\n                low = middle\n            else:\n                price = middle\n    net = value - price * cost\n    best = net.argmax(1)\n    return best, net[rows, best]\n\n\ndef best_cutoff(score, arm, t, y):\n    \"\"\"The share of validation rows, in score order, where the total observed uplift peaks. None without both groups to compare.\"\"\"\n    keep = (t == 0) | (t == arm)\n    order = np.argsort(-score[keep], kind='stable')\n    treated, outcome = t[keep][order] > 0, y[keep][order]\n    if not treated.any() or treated.all():\n        return None\n    n_t, n_c = np.cumsum(treated), np.cumsum(~treated)\n    y_t, y_c = np.cumsum(outcome * treated), np.cumsum(outcome * ~treated)\n    both = np.flatnonzero((n_t > 0) & (n_c > 0))\n    total = (y_t[both] / n_t[both] - y_c[both] / n_c[both]) * (both + 1)\n    grid = np.unique(np.searchsorted(both, np.ceil(np.arange(1, 101) / 100 * len(order)).astype(np.int64) - 1).clip(max=len(both) - 1))  # 1% steps\n    return float((both[grid[total[grid].argmax()]] + 1) / len(order))\n\n\ndef select(mode, score, eligible, chosen, matrix, effect, default, unit_cost=None, unit_gain=None, budget=None, efficiency=None, cutoff=None):\n    \"\"\"Who is treated this cycle: the candidates in order, how many from the top, each one's treatment, and the planned cost.\n\n    quantile    the top share by score\n    budget      by score, up to the user just before the budget runs out\n    knapsack    value − λ·cost > 0, with λ set so that the spend meets the budget; this also picks the treatment\n    roi         by value / cost, up to the last user at which the expected efficiency still meets the target\n    validation  by score, up to the share where the total uplift peaked on the validation rows\n\n    `effect` says the score is an expected effect. Otherwise knapsack and roi keep the model's order: dividing a random score or\n    an effect net of cost by cost has no meaning. Without an estimate yet (cycle 1), every rule takes the default share.\n    \"\"\"\n    key = score if eligible is None else np.where(eligible, score, -np.inf)\n    take, positive, spend = default, None, None\n    if mode == 'validation' and cutoff is not None:\n        take = round(cutoff * len(score))\n    if unit_cost is not None:\n        if effect and mode in ('knapsack', 'roi'):\n            value = matrix if eligible is None else np.where(eligible[:, None], matrix, -np.inf)\n            if mode == 'knapsack':\n                best, key = knapsack(value, unit_cost, budget)\n            else:\n                ratio = value / unit_cost\n                best = ratio.argmax(1)\n                key = ratio[np.arange(len(best)), best]\n            chosen, positive = best + 1, int((key > 0).sum())\n    order = np.argsort(-key, kind='stable')\n    if unit_cost is not None:\n        spend = np.cumsum(unit_cost[order, chosen[order] - 1])\n        if mode in BUDGET_MODES:\n            take = int(np.searchsorted(spend, budget, side='right'))\n        else:\n            reachable = np.flatnonzero(np.cumsum(unit_gain[order, chosen[order] - 1]) >= efficiency * spend)\n            take = int(reachable[-1]) + 1 if len(reachable) else 0\n    if positive is not None:\n        take = min(take, positive)\n    if eligible is not None:\n        take = min(take, int(eligible.sum()))\n    planned = None if spend is None else float(spend[take - 1]) if take else 0.\n    return order, take, chosen, planned\n\n\ndef trace(pop, ex, cand, picks, seed, cycle):\n    \"\"\"A sample of one cycle's rows so people can follow them: what each algorithm scored them, and what happened.\n\n    With one treatment, T, outcome and cost are fixed per person, so a row reads the same for every algorithm that selected\n    it. With several treatments they depend on the treatment each algorithm chose, so they are kept per algorithm.\n    Rows no algorithm selected were never treated or measured; the screen shows them as such.\n    \"\"\"\n    n, K = len(pop), pop.treatments\n    keep = set(np.random.default_rng(seed_of(seed, 'trace', cycle)).choice(n, size=min(TRACE_SAMPLE, n), replace=False).tolist())\n    for order, _, _ in picks.values():\n        keep.update(cand[order[:TRACE_TOP]].tolist())\n    idx = np.array(sorted(keep))\n    t = pop.assign(idx)\n    y, cost = pop.outcome(idx, t)\n    explore = np.zeros(n, dtype=bool)\n    explore[ex] = True\n    round3 = lambda a: np.round(np.asarray(a, dtype=np.float64), 3).tolist()  # noqa: E731\n    arms = {}\n    for arm_id, (order, score, chosen) in picks.items():\n        rank, full = np.zeros(n, dtype=np.int64), np.full(n, np.nan)\n        rank[cand[order]] = np.arange(1, len(cand) + 1)\n        full[cand] = score\n        arms[arm_id] = {'rank': [int(r) or None for r in rank[idx]], 'score': [None if np.isnan(v) else float(f'{v:.4g}') for v in full[idx]]}\n        if K > 1:\n            plan = pop.explore_arm(np.arange(n))\n            plan[cand] = chosen\n            given = pop.assign(idx, plan[idx])\n            yr, yc = pop.outcome(idx, given)\n            arms[arm_id].update(arm=[int(a) for a in plan[idx]], t=[int(v) for v in given], y=round3(yr), cost=round3(yc))\n            if pop.tau_r is not None:\n                tr, tc = pop.truth(idx, plan[idx])\n                arms[arm_id].update(tauR=round3(tr), tauC=round3(tc))\n    out = {'ids': [pop.ids[i] for i in idx], 'X': np.round(pop.X[idx][:, :TRACE_FEATURES], 3).tolist(), 'explore': explore[idx].tolist(),\n           't': [int(v) for v in t], 'y': round3(y), 'cost': round3(cost),\n           'split': ['train' if u < .6 else 'validation' if u < .8 else 'test' for u in pop.u_split[idx]], 'arms': arms}\n    if pop.tau_r is not None and K == 1:\n        out.update(tauR=round3(pop.tau_r[idx]), tauC=round3(pop.tau_c[idx]))\n    return out\n\n\nclass Arm:\n    def __init__(self, algorithm):\n        self.algorithm = {'id': algorithm['id'], 'name': algorithm.get('name') or algorithm['id'], 'code': algorithm['code']}\n        self.id, self.name = self.algorithm['id'], self.algorithm['name']\n        self.model, self.version, self.rows, self.served = None, 0, [], []\n\n\nclass Run:\n    def __init__(self, scenario, algorithms, explore=.2, target=.4, seed=42, window=3, device='cpu', mode='quantile', budget=.4, base_learner='ridge', efficiency=.2):\n        if not algorithms:\n            raise ValueError('알고리즘을 하나 이상 고르세요.')\n        if len({a['id'] for a in algorithms}) != len(algorithms):\n            raise ValueError('같은 알고리즘이 두 번 들어 있어요.')\n        if not (0 < explore < 1 and 0 < target <= 1 and 0 < budget <= 1):\n            raise ValueError('Explore 비율, Exploit 비율, 예산 비율은 0과 1 사이여야 해요.')\n        if not 0 <= efficiency <= 5:\n            raise ValueError('최소 효율 개선은 0과 5 사이여야 해요.')\n        if mode not in MODES:\n            raise ValueError(f'알 수 없는 선정 방식이에요: {mode}')\n        if base_learner not in BASE_LEARNERS:\n            raise ValueError(f'알 수 없는 기본 모델이에요: {base_learner}')\n        self.scenario, self.explore, self.target, self.seed, self.window, self.device = scenario, explore, target, seed, window, device\n        self.mode, self.budget, self.base_learner, self.efficiency = mode, budget, base_learner, efficiency\n        self.arms = [Arm(a) for a in algorithms]\n        self.cycle, self.log = 0, []\n\n    @property\n    def done(self):\n        return self.cycle >= self.scenario.cycles\n\n    @property\n    def share(self):\n        \"\"\"The share of candidates that uplift@k and cycle 1 use: q, or the budget share under a budget.\"\"\"\n        return self.budget if self.mode in BUDGET_MODES else self.target\n\n    def plan(self):\n        n = self.scenario.pool\n        k = round(n * self.explore)\n        return {'cycles': self.scenario.cycles, 'pool': n, 'exploreN': k, 'selectedN': round((n - k) * self.share), 'explore': self.explore,\n                'target': self.target, 'seed': self.seed, 'window': self.window, 'truth': self.scenario.truth, 'features': list(self.scenario.features),\n                'mode': self.mode, 'budget': self.budget, 'efficiency': self.efficiency, 'baseLearner': self.base_learner, 'treatments': self.scenario.treatments, 'labels': list(self.scenario.labels),\n                'algorithms': [{'id': a.id, 'name': a.name} for a in self.arms]}\n\n    def step(self, report=lambda message: None):\n        if self.done:\n            raise ValueError('이미 끝난 실행이에요.')\n        self.cycle += 1\n        c, pop = self.cycle, self.scenario.cohort(self.cycle)\n        n, K = len(pop), pop.treatments\n        order = np.argsort(pop.u_explore, kind='stable')\n        k = round(n * self.explore)\n        ex, cand = order[:k], order[k:]\n        t_ex = pop.assign(ex)\n        yr_ex, yc_ex = pop.outcome(ex, t_ex)\n        explore = cell(t_ex, yr_ex, yc_ex)\n        ex_boot = boot(t_ex, yr_ex, yc_ex, seed_of(self.seed, 'boot', 'explore', c))\n        truth = pop.tau_r is not None\n        ex_truth = None\n        if truth:\n            ex_tr, ex_tc = pop.truth(ex, pop.explore_arm(ex))\n            ex_truth = (float(ex_tr.sum()), float(ex_tc.sum()))\n            explore['truthR'] = ex_truth[0] / ex_truth[1]\n        m = round(len(cand) * self.share)\n        v0 = np.random.default_rng(seed_of(self.seed, 'v0', c)).random(len(cand))\n        v0_arm = np.ones(len(cand), dtype=np.int64)\n        if K > 1:\n            v0_arm = 1 + np.random.default_rng(seed_of(self.seed, 'v0-arm', c)).integers(0, K, len(cand))\n        unit_cost, unit_gain, budget_total, efficiency_target, held_out = None, None, None, None, None\n        if self.log:  # cycle 1 has no estimate yet, so every rule selects the same share at random\n            if self.mode in BUDGET_MODES or self.mode == 'roi':\n                unit_cost = cost_estimator(self.log, K)(pop.X[cand])\n            if self.mode in BUDGET_MODES:\n                budget_total = self.budget * float(unit_cost.mean(1).sum())\n            if self.mode == 'roi':\n                unit_gain = gain_estimator(self.log, K)(pop.X[cand])\n                efficiency_target = (1 + self.efficiency) * max(float(unit_gain.mean(1).sum() / unit_cost.mean(1).sum()), 0.)\n            if self.mode == 'validation':\n                held_out = {k: np.concatenate([b[k] for b in self.log]) for k in ('X', 't', 'y', 'split')}\n                inside = (held_out['split'] >= .6) & (held_out['split'] < .8)\n                held_out = {k: v[inside] for k, v in held_out.items()}\n        rows, picks = [], {}\n        for arm in self.arms:\n            report({'cycle': c, 'arm': arm.id, 'phase': 'score'})\n            row = {'cycle': c, 'arm': arm.id, 'version': arm.version, 'error': None}\n            score, eligible, chosen, matrix, effect, cutoff, started = v0, None, v0_arm, None, False, None, time.perf_counter()\n            if arm.model is not None:\n                try:\n                    score, eligible, chosen, matrix = contract.decide(arm.model, pop.X[cand], K)\n                    effect = getattr(arm.model, 'score_is_effect', True)\n                    if held_out is not None:\n                        v_score, _, v_arm = contract.scores(arm.model, held_out['X'], K)\n                        cutoff = best_cutoff(v_score, v_arm, held_out['t'], held_out['y'])\n                except Exception as error:  # a model that cannot score falls back to random for this cycle\n                    score, eligible, chosen, matrix, effect, cutoff, row['error'] = v0, None, v0_arm, None, False, None, f'predict · {contract.explain(error)}'\n            row['scoringMs'] = (time.perf_counter() - started) * 1000\n            order_sel, take, chosen, planned = select(self.mode, score, eligible, chosen, matrix, effect, m, unit_cost, unit_gain, budget_total, efficiency_target, cutoff)\n            sel, sel_arm = cand[order_sel[:take]], chosen[order_sel[:take]]\n            picks[arm.id] = (order_sel, score, chosen)\n            t_sel = pop.assign(sel, sel_arm)\n            measured = (t_sel == 0) | (t_sel == sel_arm)  # with logged data, a row logged under another treatment says nothing about this one\n            t_sel = t_sel[measured]\n            yr_sel, yc_sel = pop.outcome(sel[measured], t_sel)\n            exploit = cell(t_sel, yr_sel, yc_sel)\n            sel_boot = boot(t_sel, yr_sel, yc_sel, seed_of(self.seed, 'boot', arm.id, c))\n            row.update(selected=int(take), exploit=exploit, R=exploit['R'], gain=None, ci=[None, None], profile=pop.X[sel].mean(0).tolist() if take else None,\n                       incR=None if exploit['ateR'] is None else exploit['ateR'] * take, incC=None if exploit['ateC'] is None else exploit['ateC'] * take, planned=planned, cutoff=cutoff)\n            if K > 1:\n                row['armCounts'] = np.bincount(sel_arm.astype(np.intp), minlength=K + 1)[1:].tolist()  # the browser's Python is 32-bit: bincount refuses int64 there\n            if exploit['R'] is not None and explore['R']:\n                row['gain'] = exploit['R'] / explore['R'] - 1\n            if sel_boot and ex_boot:\n                row['ci'] = interval(relative(ratio_of(sel_boot), ratio_of(ex_boot)))\n            if truth:\n                tr_v, tc_v = pop.truth(sel, sel_arm)\n                tr, tc = float(tr_v.sum()), float(tc_v.sum())\n                row.update(truthR=tr / tc if tc else None, truthGain=(tr / tc) / explore['truthR'] - 1 if tc else None, truthIncR=tr, truthIncC=tc)\n            if arm.version > 0 and sel_boot and ex_boot:\n                arm.served.append({'w': take, 'sel': exploit, 'ex': explore, 'selBoot': sel_boot, 'exBoot': ex_boot,\n                                   'truth': (tr, tc, ex_truth[0] / k * take, ex_truth[1] / k * take) if truth else None, 'armCounts': row.get('armCounts')})\n            arm.rows.append(row)\n            rows.append(row)\n        self.log.append({'cycle': c, 'X': pop.X[ex], 't': t_ex, 'y': yr_ex, 'cost': yc_ex, 'split': pop.u_split[ex],\n                         'tau_r': pop.tau_r[ex] if truth else None, 'tau_c': pop.tau_c[ex] if truth else None})\n        self.log = [b for b in self.log if b['cycle'] > c - self.window]\n        sets = splits(self.log, self.scenario)\n        for arm, row in zip(self.arms, rows):\n            report({'cycle': c, 'arm': arm.id, 'phase': 'train'})\n            try:\n                model, out = fit(arm.algorithm, sets, self.seed, c, self.share, self.device, report, self.base_learner)\n                row['train'] = {**out, **evaluate(model, sets['test'], self.share), 'version': arm.version + 1}\n                arm.model, arm.version = model, arm.version + 1\n            except Exception as error:  # keep serving the previous model, as production would\n                row['train'] = {'error': contract.explain(error)}\n            report({'cycle': c, 'arm': arm.id, 'phase': 'done'})\n        return {'cycle': c, 'done': self.done, 'n': n, 'candidates': int(len(cand)), 'explore': explore, 'budget': budget_total, 'efficiencyTarget': efficiency_target,\n                'pool': {'mean': pop.X[cand].mean(0).tolist(), 'std': pop.X[cand].std(0).tolist()}, 'trace': trace(pop, ex, cand, picks, self.seed, c),\n                'window': {'cycles': [b['cycle'] for b in self.log], 'rows': int(sum(len(b['t']) for b in self.log)), 'split': {k: int(len(v.t)) for k, v in sets.items()}},\n                'arms': rows, 'summary': self.summary()}\n\n    def summary(self):\n        \"\"\"Pooled over the cycles each algorithm served with its own model (cycle 2 onward).\n\n        A fixed share ranks by efficiency gain, since every algorithm treats as many users. Under a budget every algorithm\n        spends about the same, so the rank is how much incremental outcome that spend bought. The roi and validation rules let\n        the group size differ too, and also rank by incremental outcome. Under roi an algorithm that missed the efficiency\n        target ranks after those that met it.\n        \"\"\"\n        out, draws, volume = [], {}, {}\n        for arm in self.arms:\n            S, trained = arm.served, [r['train'] for r in arm.rows if r.get('train') and 'error' not in r['train']]\n            s = {'arm': arm.id, 'name': arm.name, 'cycles': len(S), 'gain': None, 'ci': [None, None], 'incR': None, 'incC': None, 'R': None, 'baseR': None, 'selected': None,\n                 'truthGain': None, 'truthIncR': None, 'truthIncC': None, 'truthR': None, 'baseTruthR': None, 'armShare': None,\n                 'aucc': None, 'auccTruth': None, 'qini': None, 'qiniTruth': None, 'upliftAt': None, 'upliftAtTruth': None, 'trainMs': None,\n                 'failures': sum(1 for r in arm.rows if r.get('error') or 'error' in r.get('train', {})),\n                 'lastError': next((r.get('error') or r.get('train', {}).get('error') for r in reversed(arm.rows) if r.get('error') or 'error' in r.get('train', {})), None)}\n            if trained:\n                s.update(trainMs=float(np.mean([t['ms'] for t in trained])), **{key: _mean(t.get(key) for t in trained) for key in ('aucc', 'auccTruth', 'qini', 'qiniTruth', 'upliftAt', 'upliftAtTruth')})\n            if S:\n                w = np.array([p['w'] for p in S], dtype=np.float64)\n                sel_r, sel_c = np.array([p['sel']['ateR'] for p in S]) @ w, np.array([p['sel']['ateC'] for p in S]) @ w\n                ex_r, ex_c = np.array([p['ex']['ateR'] for p in S]) @ w, np.array([p['ex']['ateC'] for p in S]) @ w\n                s.update(incR=float(sel_r), incC=float(sel_c), R=float(sel_r / sel_c) if sel_c else None, baseR=float(ex_r / ex_c) if ex_c else None, selected=float(w.mean()))\n                pool = lambda key, i: sum(wi * p[key][i] for wi, p in zip(w, S))  # noqa: E731\n                volume[arm.id] = pool('selBoot', 0)\n                if sel_c and ex_c and ex_r:\n                    s['gain'] = float((sel_r / sel_c) / (ex_r / ex_c) - 1)\n                    draws[arm.id] = relative(ratio_of((pool('selBoot', 0), pool('selBoot', 1))), ratio_of((pool('exBoot', 0), pool('exBoot', 1))))\n                    s['ci'] = interval(draws[arm.id])\n                if S[0]['truth']:\n                    tr, tc, er, ec = (sum(p['truth'][i] for p in S) for i in range(4))\n                    s.update(truthIncR=tr, truthIncC=tc, truthR=tr / tc, baseTruthR=er / ec, truthGain=(tr / tc) / (er / ec) - 1)\n                if S[0]['armCounts']:\n                    counts = np.sum([p['armCounts'] for p in S], axis=0)\n                    s['armShare'] = (counts / max(counts.sum(), 1)).tolist()\n            out.append(s)\n        by_volume = self.mode != 'quantile'\n        key = ('truthIncR' if by_volume else 'truthGain') if self.scenario.truth else ('incR' if by_volume else 'gain')\n        gain_key = 'truthGain' if self.scenario.truth else 'gain'\n        for s in out:\n            s['meets'] = None if self.mode != 'roi' or s[gain_key] is None else s[gain_key] >= self.efficiency\n        ranked = sorted(out, key=lambda s: (s[key] is None, s['meets'] is False, -(s[key] or 0)))  # no result ranks last\n        for i, s in enumerate(ranked):\n            s['rank'], s['vsLeader'] = i + 1, None\n        leader = ranked[0]\n        spread, field = (volume, 'incR') if by_volume else (draws, 'gain')\n        for s in ranked[1:]:  # explore draws are shared, so the baseline noise cancels in the difference\n            if s['arm'] in spread and leader['arm'] in spread and s[field] is not None and leader[field] is not None:\n                ci = interval(spread[s['arm']] - spread[leader['arm']])\n                s['vsLeader'] = {'diff': s[field] - leader[field], 'ci': ci, 'tied': ci[0] is not None and ci[0] <= 0 <= ci[1]}\n        return {'by': key, 'leader': leader['arm'], 'arms': out}\n\n\ndef _mean(values):\n    values = [v for v in values if v is not None]\n    return float(np.mean(values)) if values else None\n\n\ndef quick_check(algorithm, device='cpu', report=lambda message: None, seed=42):\n    \"\"\"Fit once on three cycles of explore data from the base synthetic market, to catch errors before a full run.\"\"\"\n    scenario, log = SyntheticScenario('base', seed=seed, pool=20000, cycles=3), []\n    for c in range(1, 4):\n        pop = scenario.cohort(c)\n        ex = np.argsort(pop.u_explore, kind='stable')[:round(len(pop) * .2)]\n        t = pop.assign(ex)\n        y, cost = pop.outcome(ex, t)\n        log.append({'cycle': c, 'X': pop.X[ex], 't': t, 'y': y, 'cost': cost, 'split': pop.u_split[ex], 'tau_r': pop.tau_r[ex], 'tau_c': pop.tau_c[ex]})\n    sets = splits(log, scenario)\n    model, out = fit(algorithm, sets, seed, 3, .4, device, report)\n    started = time.perf_counter()\n    result = evaluate(model, sets['test'], .4)\n    return {**out, **result, 'predictMs': (time.perf_counter() - started) * 1000, 'split': {k: int(len(v.t)) for k, v in sets.items()}}\n","upliftlab/bridge.py":"\"\"\"JSON entry points shared by the browser worker (Pyodide) and the local server.\"\"\"\nimport json\nimport math\nimport platform\nimport sys\nimport traceback\nfrom pathlib import Path\n\nimport numpy as np\n\nfrom . import __version__, contract, datasets\nfrom .algorithms import ORDER\nfrom .arena import Run, quick_check\nfrom .scenario import ReplayScenario, SyntheticScenario\n\nstate = {'run': None, 'data': {}, 'report': lambda message: None, 'runtime': 'browser', 'device': 'cpu', 'devices': ['cpu']}\nALGORITHM_DIR = Path(__file__).parent / 'algorithms'\nTEMPLATE_DIR = Path(__file__).parent / 'templates'\nTEMPLATES = ['start_sklearn', 'start_lightgbm', 'start_pytorch']  # starting files for a new algorithm, in menu order\n\n\ndef clean(value):\n    if isinstance(value, dict):\n        return {str(k): clean(v) for k, v in value.items()}\n    if isinstance(value, (list, tuple)):\n        return [clean(v) for v in value]\n    if isinstance(value, (np.integer,)):\n        return int(value)\n    if isinstance(value, (float, np.floating)):\n        return float(value) if math.isfinite(value) else None\n    if isinstance(value, np.ndarray):\n        return clean(value.tolist())\n    return value\n\n\ndef set_reporter(fn):\n    state['report'] = fn\n\n\ndef report(message):\n    state['report'](json.dumps(clean(message)))\n\n\ndef _files(folder, keys):\n    \"\"\"Algorithm files with what they declare, read without running them (so listing never needs their libraries).\"\"\"\n    out = []\n    for key in keys:\n        code = (folder / f'{key}.py').read_text(encoding='utf-8')\n        meta = contract.describe(code, f'{key}.py')\n        out.append({'id': key, 'name': meta['name'] or key, 'summary': meta['summary'], 'code': code, 'file': f'upliftlab/{folder.name}/{key}.py',\n                    'libraries': contract.libraries(meta['imports'], meta['requires'])})\n    return out\n\n\ndef builtins():\n    return [{**a, 'builtin': True} for a in _files(ALGORITHM_DIR, ORDER)]\n\n\ndef templates():\n    return _files(TEMPLATE_DIR, TEMPLATES)\n\n\ndef info():\n    return {'engine': __version__, 'python': platform.python_version(), 'numpy': np.__version__, 'runtime': state['runtime'],\n            'device': state['device'], 'devices': state['devices'], 'algorithms': builtins(), 'templates': templates(),\n            'libraries': contract.libraries(contract.COMMON), 'datasets': datasets.catalog()}\n\n\ndef check(code, id='algorithm'):\n    \"\"\"Reads the file, then runs its top level (imports included) and checks class Model. Missing libraries say what to do.\"\"\"\n    filename = f'{id}.py'\n    try:\n        meta = contract.describe(code, filename)\n    except SyntaxError as error:\n        return {'ok': False, 'error': f'SyntaxError: {error.msg}', 'line': error.lineno, 'libraries': []}\n    out = {'name': meta['name'], 'summary': meta['summary'], 'requires': meta['requires'], 'libraries': contract.libraries(meta['imports'], meta['requires'])}\n    try:\n        contract.load(code, filename)\n        return {'ok': True, **out}\n    except Exception as error:\n        return {'ok': False, **out, 'error': contract.explain(error), 'line': contract.line(error, filename)}\n\n\ndef requirements(codes):\n    \"\"\"PEP 723 dependencies of these files that are not installed yet.\"\"\"\n    return contract.pending(codes)\n\n\nasync def prepare(codes):\n    \"\"\"Browser only: install declared PEP 723 dependencies with micropip. Failures are kept and shown by check().\"\"\"\n    import micropip\n    for requirement in contract.pending(codes):\n        package = contract.distribution(requirement)\n        try:\n            await micropip.install(requirement)\n            contract.install_errors.pop(package, None)\n        except Exception as error:\n            contract.install_errors[package] = str(error).strip().splitlines()[0][:160]\n\n\ndef try_algorithm(code, id='algorithm', name=None):\n    \"\"\"Quick check on the base synthetic market. Errors come back with the line in the user's file.\"\"\"\n    try:\n        return {'ok': True, **quick_check({'id': id, 'name': name or id, 'code': code}, state['device'], report)}\n    except Exception as error:\n        return {'ok': False, 'error': contract.explain(error), 'line': contract.line(error, f'{id}.py')}\n\n\ndef inspect_csv(csv):\n    return datasets.inspect(csv)\n\n\ndef add_dataset(id, csv, name, mapping=None):\n    data = datasets.parse(csv, mapping)\n    state['data'][id] = data\n    return {'id': id, 'name': name, 'mapping': data.mapping, 'profile': datasets.profile(data.X, data.t, data.y, data.cost, data.features, filled=data.filled)}\n\n\ndef sample_csv():\n    \"\"\"The example experiment log offered on the upload screen.\"\"\"\n    return {'name': datasets.SAMPLE_NAME, 'csv': datasets.sample_csv()}\n\n\ndef fetch_dataset(id):\n    if state['runtime'] != 'local':\n        raise ValueError('원본 사이트가 브라우저 다운로드를 막고 있어요. 파일을 받아 업로드하거나 로컬에서 실행해 주세요.')\n    meta = next(d for d in datasets.PUBLIC if d['id'] == id)\n    return add_dataset(id, datasets.fetch(id), meta['name'])\n\n\ndef describe_dataset(id, seed=42):\n    if id.startswith('synthetic/'):\n        return {'id': id, 'profile': datasets.profile_synthetic(id, seed)}\n    data = state['data'].get(id)\n    if data is None:\n        return {'id': id, 'loaded': False}\n    return {'id': id, 'loaded': True, 'mapping': data.mapping, 'profile': datasets.profile(data.X, data.t, data.y, data.cost, data.features, filled=data.filled)}\n\n\ndef run_start(dataset, algorithms, cycles=8, explore=.2, target=.4, seed=42, window=3, mode='quantile', budget=.4, base_learner='ridge', efficiency=.2):\n    cycles = int(min(12, max(2, cycles)))\n    if dataset.startswith('synthetic/'):\n        scenario = SyntheticScenario(datasets.synthetic_preset(dataset), seed=seed, cycles=cycles)\n    elif dataset in state['data']:\n        scenario = ReplayScenario(state['data'][dataset], seed=seed, cycles=cycles)\n    else:\n        raise LookupError(f'데이터를 먼저 불러와 주세요: {dataset}')\n    for a in algorithms:  # a file that cannot even load (a missing library, a syntax error) stops the run before it starts\n        try:\n            contract.load(a['code'], f\"{a['id']}.py\")\n        except Exception as error:\n            raise ValueError(f\"{a.get('name') or a['id']} · {contract.explain(error)}\") from None\n    state['run'] = Run(scenario, algorithms, explore=explore, target=target, seed=seed, window=window, device=state['device'], mode=mode, budget=budget, base_learner=base_learner, efficiency=efficiency)\n    return {**state['run'].plan(), 'dataset': dataset, 'engine': __version__, 'runtime': state['runtime'], 'device': state['device']}\n\n\ndef run_cycle():\n    if state['run'] is None:\n        raise ValueError('시작한 실행이 없어요.')\n    return state['run'].step(report)\n\n\ndef record(plan, cycles):\n    \"\"\"The saved form of a run: per-cycle results, the final summary, and cost curves only for the last cycle.\"\"\"\n    rows = []\n    for i, c in enumerate(cycles):\n        c = {k: v for k, v in c.items() if k != 'summary'}\n        if i < len(cycles) - 1:\n            c['arms'] = [{**a, 'train': {k: v for k, v in (a.get('train') or {}).items() if k not in ('curve', 'truthCurve')}} for a in c['arms']]\n        rows.append(c)\n    return {'plan': plan, 'cycles': rows, 'summary': cycles[-1]['summary'] if cycles else None}\n\n\ndef run_all(dataset, algorithms, cycles=8, explore=.2, target=.4, seed=42, mode='quantile', budget=.4, base_learner='ridge', efficiency=.2):\n    plan, out = run_start(dataset, algorithms, cycles, explore, target, seed, mode=mode, budget=budget, base_learner=base_learner, efficiency=efficiency), []\n    while not state['run'].done:\n        out.append(run_cycle())\n    return clean(record(plan, out))\n\n\nMETHODS = {f.__name__: f for f in (info, check, requirements, try_algorithm, inspect_csv, add_dataset, sample_csv, fetch_dataset, describe_dataset, run_start, run_cycle, run_all)}\n\n\ndef call(method, payload='{}'):\n    \"\"\"Returns a JSON string: {\"ok\": true, \"result\": …} or {\"ok\": false, \"error\": traceback}.\"\"\"\n    try:\n        if method not in METHODS:\n            raise ValueError(f'unknown method {method}')\n        return json.dumps({'ok': True, 'result': clean(METHODS[method](**json.loads(payload)))}, ensure_ascii=False)\n    except Exception as error:\n        tb = traceback.format_exc(limit=6)\n        return json.dumps({'ok': False, 'error': f'{type(error).__name__}: {error}', 'trace': tb[-4000:]}, ensure_ascii=False)\n\n\nif sys.platform == 'emscripten':\n    state['runtime'] = 'browser'\n","upliftlab/contract.py":"\"\"\"The algorithm contract. An algorithm is one self-contained Python file that defines `class Model`:\n\n    class Model:\n        def fit(self, train, validation, context): ...   # context is optional: fit(self, train, validation)\n        def predict(self, X): return scores                # or {\"score\": scores, \"eligible\": bool mask}\n\nThe file imports nothing from upliftlab, so it also runs in a notebook. It may import any library the runtime has.\nIn the browser, packages that Pyodide ships (NumPy, SciPy, pandas, scikit-learn, LightGBM, XGBoost, statsmodels, …)\nload on first import, and other pure-Python packages from PyPI install when the file declares them (PEP 723):\n\n    # /// script\n    # dependencies = [\"scikit-uplift\"]\n    # ///\n\nThe local edition uses whatever is installed in the Python that runs it, PyTorch on a GPU included.\n\n`train` / `validation` have X (n×d float array), t (0 = control, 1..K = treatment), y (outcome), cost, propensity,\ntreatments (K), propensities (P(T = k | T in {0, k}) per treatment) and features (column names).\nHigher score = treat first. With K treatments, predict returns an n×K array of scores, and each user gets the treatment\nwith the highest score. `context` has seed, model_seed, device ('cpu' or 'cuda:0'), target_fraction, cycle, base_learner\n('ridge' or 'tree'), treatments and report(**metrics).\n\nThe knapsack and efficiency selections read the score as an expected effect in outcome units and weigh it against cost.\nA model whose score is something else (a rank, or an effect that already subtracts cost) sets `score_is_effect = False`\non the class, and those selections keep its order as it is.\n\"\"\"\nimport ast\nimport importlib.metadata\nimport importlib.util\nimport inspect\nimport re\nimport sys\nimport traceback\nfrom types import SimpleNamespace\n\nimport numpy as np\n\nBROWSER = sys.platform == 'emscripten'\n# Import name → the package name to install, where they differ.\nPACKAGES = {'sklearn': 'scikit-learn', 'sklift': 'scikit-uplift', 'cv2': 'opencv-python', 'PIL': 'pillow', 'yaml': 'pyyaml',\n            'skimage': 'scikit-image', 'bs4': 'beautifulsoup4', 'dateutil': 'python-dateutil'}\n# Common libraries that Pyodide v0.27.7 ships (web/runtime.js pins that version). Used only to describe a file before\n# its imports are loaded; the worker loads any Pyodide package a file imports, listed here or not.\nPYODIDE = {'numpy': '2.0.2', 'scipy': '1.14.1', 'pandas': '2.2.3', 'sklearn': '1.6.1', 'lightgbm': '4.5.0', 'xgboost': '2.1.2',\n           'statsmodels': '0.14.4', 'polars': '1.18.0', 'pyarrow': '18.1.0', 'networkx': '3.4.2'}\n# Compiled libraries with no browser build and no pure-Python wheel: only the local edition can run them.\nLOCAL_ONLY = {'torch', 'tensorflow', 'jax', 'jaxlib', 'catboost', 'econml', 'causalml', 'cupy'}\nCOMMON = ['numpy', 'scipy', 'pandas', 'sklearn', 'lightgbm', 'xgboost', 'statsmodels', 'torch']\nENGINE = '알고리즘 파일에서는 upliftlab을 import할 수 없어요. 필요한 코드는 파일 안에 두거나 NumPy, scikit-learn 같은 라이브러리를 써 주세요.'\nBLOCK = re.compile(r'(?m)^# /// (?P<type>[a-zA-Z0-9-]+)$\\s(?P<content>(^#(| .*)$\\s)+)^# ///$')\ninstall_errors = {}  # package → why micropip could not install it (browser only)\n\n\nclass ContractError(ValueError):\n    def __init__(self, message, lineno=None):\n        super().__init__(message)\n        self.lineno = lineno\n\n\ndef dataset(X, t, y, cost, propensity, features, treatments=1, propensities=None):\n    return SimpleNamespace(X=X, t=t.astype(np.int64), y=y.astype(np.float64), cost=cost.astype(np.float64),\n                           propensity=np.full(len(t), propensity), features=list(features), treatments=treatments,\n                           propensities=np.full(treatments, float(propensity)) if propensities is None else np.asarray(propensities, dtype=np.float64))\n\n\nclass Context(SimpleNamespace):\n    \"\"\"Passed to fit(). report() streams numeric metrics (step, total, loss, …) to the screen.\"\"\"\n\n    def report(self, **metrics):\n        self._count = getattr(self, '_count', 0) + 1\n        if self._count > 2000:  # a chatty algorithm must not flood the screen\n            return\n        values = {str(k)[:32]: float(v) for k, v in list(metrics.items())[:12] if isinstance(v, (int, float, np.floating, np.integer)) and np.isfinite(v)}\n        self._emit(values)\n\n\ndef package_of(module):\n    return PACKAGES.get(module, module)\n\n\ndef normalize(name):\n    return re.sub(r'[-_.]+', '-', name).lower()\n\n\ndef requirements(code):\n    \"\"\"Dependencies declared in a PEP 723 `# /// script` block.\"\"\"\n    for match in BLOCK.finditer(code):\n        if match.group('type') != 'script':\n            continue\n        content = ''.join(line[2:] if line.startswith('# ') else line[1:] for line in match.group('content').splitlines(keepends=True))\n        try:\n            import tomllib\n            return [str(d) for d in tomllib.loads(content).get('dependencies', [])]\n        except ModuleNotFoundError:  # Python 3.10: read the list without a TOML parser\n            listed = re.search(r'(?ms)^dependencies\\s*=\\s*\\[(.*?)\\]', content)\n            return re.findall(r'[\"\\']([^\"\\']+)[\"\\']', listed.group(1)) if listed else []\n    return []\n\n\ndef distribution(requirement):\n    return re.match(r'\\s*([A-Za-z0-9][A-Za-z0-9._-]*)', requirement).group(1)\n\n\ndef installed(package):\n    try:\n        return importlib.metadata.version(package)\n    except importlib.metadata.PackageNotFoundError:\n        return None\n\n\ndef pending(codes):\n    \"\"\"Declared dependencies that are not installed yet (the browser worker installs them with micropip).\"\"\"\n    out = []\n    for code in codes:\n        for requirement in requirements(code):\n            if not installed(distribution(requirement)) and requirement not in out:\n                out.append(requirement)\n    return out\n\n\ndef describe(code, filename='algorithm.py'):\n    \"\"\"What a file declares, read without running it: NAME, the docstring summary, imports and PEP 723 dependencies.\"\"\"\n    tree = ast.parse(code, filename)\n    doc = ast.get_docstring(tree) or ''\n    name = next((node.value.value for node in tree.body if isinstance(node, ast.Assign) and isinstance(node.value, ast.Constant)\n                 and isinstance(node.value.value, str) and any(isinstance(t, ast.Name) and t.id == 'NAME' for t in node.targets)), None)\n    modules, lines = [], {}\n    for node in ast.walk(tree):\n        names = [a.name for a in node.names] if isinstance(node, ast.Import) else [node.module] if isinstance(node, ast.ImportFrom) and node.level == 0 and node.module else []\n        for full in names:\n            top = full.split('.')[0]\n            if top not in lines:\n                modules.append(top)\n                lines[top] = node.lineno\n    return {'name': name, 'summary': doc.split('\\n\\n')[0].replace('\\n', ' ') if doc else '', 'imports': modules, 'lines': lines, 'requires': requirements(code)}\n\n\ndef libraries(modules, requires=()):\n    \"\"\"Third-party imports and whether this runtime has them: ok (installed), auto (the browser loads it on first use),\n    declared (PEP 723, installed before running), local (no browser build), missing, or failed (micropip could not install it).\"\"\"\n    declared = {normalize(distribution(r)) for r in requires}\n    out = []\n    for module in modules:\n        if module in sys.stdlib_module_names or module in ('__future__', 'upliftlab'):\n            continue\n        package = package_of(module)\n        entry = {'module': module, 'package': package, 'version': None, 'status': 'missing'}\n        if importlib.util.find_spec(module) is not None:\n            entry.update(status='ok', version=installed(package))\n        elif BROWSER and module in PYODIDE:\n            entry.update(status='auto', version=PYODIDE[module])\n        elif package in install_errors:\n            entry.update(status='failed', note=install_errors[package])\n        elif BROWSER and module in LOCAL_ONLY:\n            entry['status'] = 'local'\n        elif BROWSER and normalize(package) in declared:\n            entry['status'] = 'declared'\n        out.append(entry)\n    return out\n\n\ndef missing(module):\n    package = package_of(module)\n    if BROWSER and module in LOCAL_ONLY:\n        return f'브라우저용 빌드가 없는 라이브러리예요 · {package}. 로컬(python -m upliftlab serve)에서 실행해 주세요.'\n    if BROWSER:\n        why = f' ({install_errors[package]})' if package in install_errors else ''\n        return (f'브라우저에 없는 라이브러리예요 · {package}{why}. PyPI의 순수 Python 패키지라면 파일 맨 위 # /// script 블록의 '\n                f'dependencies에 적어 주세요. 컴파일이 필요한 패키지는 로컬에서 실행해요.')\n    return f'설치되지 않은 라이브러리예요 · {package}. 실행 중인 Python 환경에서 pip install {package} 후 다시 검사해 주세요.'\n\n\ndef explain(error):\n    \"\"\"One line for the screen. A missing library comes with what to do about it in this runtime.\"\"\"\n    if isinstance(error, ModuleNotFoundError) and error.name:\n        return f'ModuleNotFoundError: {missing(error.name.split(\".\")[0])}'\n    if isinstance(error, ContractError):\n        return str(error)\n    return f'{type(error).__name__}: {error}'\n\n\ndef line(error, filename):\n    \"\"\"The line in the user's file where the error happened, if it happened there.\"\"\"\n    found = getattr(error, 'lineno', None)\n    if found is None:\n        frames = [f for f in traceback.extract_tb(error.__traceback__) if f.filename == filename]\n        found = frames[-1].lineno if frames else None\n    return found\n\n\ndef load(code, filename='algorithm.py'):\n    meta = describe(code, filename)\n    if 'upliftlab' in meta['lines']:\n        raise ContractError(ENGINE, meta['lines']['upliftlab'])\n    namespace = {'__name__': 'algorithm'}\n    exec(compile(code, filename, 'exec'), namespace)\n    model_type = namespace.get('Model')\n    if not inspect.isclass(model_type):\n        raise ContractError('class Model을 정의해 주세요.')\n    for method in ('fit', 'predict'):\n        if not callable(getattr(model_type, method, None)):\n            raise ContractError(f'class Model에 {method}() 메서드가 필요해요.')\n    return model_type, meta\n\n\ndef instantiate(model_type):\n    return model_type({}) if len(inspect.signature(model_type).parameters) else model_type()\n\n\ndef fit(model, train, validation, context):\n    \"\"\"fit(train, validation, context), or fit(train, validation) for code that does not report progress.\"\"\"\n    params = inspect.signature(model.fit).parameters.values()\n    takes_context = len(params) >= 3 or any(p.kind == p.VAR_POSITIONAL for p in params)\n    return model.fit(train, validation, context) if takes_context else model.fit(train, validation)\n\n\ndef scores(model, X, treatments=1):\n    \"\"\"What a model decides for each row: its score, whether it may be selected, and which treatment (1..K) it would get.\"\"\"\n    return decide(model, X, treatments)[:3]\n\n\ndef decide(model, X, treatments=1):\n    \"\"\"scores(), plus the n×K score of every treatment. A model that names one treatment per row has a score for that one only.\"\"\"\n    out = model.predict(X)\n    eligible, arm, matrix = None, None, None\n    if isinstance(out, dict):\n        if 'score' not in out:\n            raise ValueError('predict(X)는 점수 배열이나 {\"score\": 배열}을 반환해야 해요.')\n        score, eligible, arm = out['score'], out.get('eligible'), out.get('arm')\n    else:\n        score = out\n    if hasattr(score, 'detach'):  # a torch tensor\n        score = score.detach().cpu().numpy()\n    score = np.asarray(score, dtype=np.float64)\n    if score.ndim == 2 and score.shape[1] == treatments and arm is None:\n        matrix = score\n        arm = score.argmax(1) + 1\n        score = score.max(1)\n    elif treatments > 1 and arm is None:\n        raise ValueError(f'이 데이터셋의 처치는 {treatments}종류예요. predict는 (행 수, {treatments}) 배열이나 {{\"score\": 배열, \"arm\": 처치 번호}}를 반환해야 해요.')\n    score = score.reshape(-1)\n    if score.shape != (len(X),) or not np.isfinite(score).all():\n        raise ValueError('score는 입력 행 수와 같은 길이의 유한한 배열이어야 해요.')\n    if eligible is not None:\n        eligible = np.asarray(eligible)\n        if eligible.shape != (len(X),) or eligible.dtype.kind != 'b':\n            raise ValueError('eligible은 입력 행 수와 같은 길이의 불리언 배열이어야 해요.')\n    arm = np.ones(len(X), dtype=np.int64) if arm is None else np.asarray(arm, dtype=np.int64).reshape(-1)\n    if arm.shape != (len(X),) or arm.min() < 1 or arm.max() > treatments:\n        raise ValueError(f'arm은 입력 행 수와 같은 길이의 처치 번호(1~{treatments}) 배열이어야 해요.')\n    if matrix is None or not np.isfinite(matrix).all():\n        matrix = np.full((len(X), treatments), -np.inf)\n        matrix[np.arange(len(X)), arm - 1] = score\n    return score, eligible, arm, matrix\n","upliftlab/datasets.py":"\"\"\"Datasets: built-in synthetic markets, public experiments fetched from their source, and uploaded CSV files.\n\nPublic files are never bundled. The local edition downloads them from the source; in the browser the user uploads the\nfile they downloaded, and known schemas (such as Hillstrom) are converted automatically.\n\"\"\"\nimport csv\nimport hashlib\nimport io\nimport re\nimport urllib.request\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport numpy as np\n\nfrom .scenario import SyntheticScenario\n\nSYNTHETIC = [\n    {'id': 'synthetic/base', 'preset': 'base', 'name': '기본 시장',\n     'summary': '공변량 4개가 고르게 분포해요. 이용 공백이 긴 사용자의 증분 효과가 커요.'},\n    {'id': 'synthetic/loyal', 'preset': 'loyal', 'name': '고빈도 사용자 시장',\n     'summary': '이용 빈도가 높은 사용자가 많아요. 처치 없이도 리텐션이 높아 증분 효과가 작은 사용자 비중이 커요.'},\n    {'id': 'synthetic/premium', 'preset': 'premium', 'name': '고액 결제 시장',\n     'summary': '결제액과 가격 민감도가 높아요. 증분 효과가 크지만 증분 비용도 커요.'},\n    {'id': 'synthetic/tiers', 'preset': 'tiers', 'name': '다단계 보상 시장', 'treatment': '미지급 = 0, 보상 ×0.5 = 1, 보상 ×1 = 2, 보상 ×1.5 = 3',\n     'summary': '처치가 3종류예요. 보상이 클수록 효과는 포화되고 비용은 커져서, 사용자별로 어떤 보상을 줄지 함께 결정해요.'},\n]\nSYNTHETIC_FIELDS = {'outcome': '리텐션 (0/1)', 'treatment': '보상 지급 = 1, 미지급 = 0', 'cost': '보상 사용액'}\n\nHILLSTROM = {\n    'id': 'public/hillstrom', 'name': 'Hillstrom 이메일 실험', 'rows': 64000,\n    'summary': '사용자 64,000명에게 이메일을 무작위 배정한 2008년 실험이에요. 2주 내 사이트 방문이 결과예요.',\n    'source': 'https://blog.minethatdata.com/2008/03/minethatdata-e-mail-analytics-and-data.html',\n    'download': 'http://www.minethatdata.com/Kevin_Hillstrom_MineThatData_E-MailAnalytics_DataMiningChallenge_2008.03.20.csv',\n    'license': '명시된 라이선스가 없어 파일을 함께 배포하지 않아요. 원본에서 받아 사용해 주세요.',\n    'treatment': '이메일 발송 (남성용·여성용) = 1, 미발송 = 0', 'outcome': 'visit · 2주 안 방문 (0/1)', 'cost': '열 없음 · 발송 1건당 1',\n}\nHILLSTROM_COLUMNS = {'recency', 'history', 'mens', 'womens', 'zip_code', 'newbie', 'channel', 'segment', 'visit'}\nPUBLIC = [HILLSTROM]\n\nTREATMENT_NAMES = {'t', 'treatment', 'treated', 'treat', 'w', 'group', 'coupon', 'voucher', 'promo', 'promotion', 'reward', 'offer', 'campaign', 'email', 'exposed', 'sent', 'dose', 'arm', 'variant'}\nOUTCOME_NAMES = {'y', 'outcome', 'conversion', 'converted', 'convert', 'retained', 'retention', 'yr', 'visit', 'visited', 'return', 'returned', 'response', 'purchase', 'purchased', 'bought', 'order', 'ordered', 'click', 'clicked', 'revenue', 'target', 'label'}\nCOST_NAMES = {'cost', 'yc', 'spend', 'spent', 'expense'}\nID_NAMES = {'id', 'user_id', 'userid', 'customer_id', 'index', 'row', 'uid'}\nMIN_ROWS = 1000\nMAX_LEVELS = 20  # a text column with more distinct values than this cannot become a feature\nMAX_TREATMENTS = 8\nBLANKS = {'', 'na', 'n/a', 'nan', 'null', 'none'}\n\n\ndef catalog():\n    synthetic = [{**SYNTHETIC_FIELDS, **d, 'kind': 'synthetic', 'truth': True, 'features': SyntheticScenario.features, 'pool': 20000, 'treatments': len(SyntheticScenario.LEVELS.get(d['preset'], SyntheticScenario.SINGLE)['cost'])} for d in SYNTHETIC]\n    return synthetic + [{**d, 'kind': 'public', 'truth': False} for d in PUBLIC]\n\n\ndef synthetic_preset(dataset_id):\n    preset = next((d['preset'] for d in SYNTHETIC if d['id'] == dataset_id), None)\n    if preset is None:\n        raise ValueError(f'알 수 없는 데이터예요: {dataset_id}')\n    return preset\n\n\ndef read(text):\n    text = text.lstrip('﻿')\n    try:\n        dialect = csv.Sniffer().sniff(text[:4096], delimiters=',;\\t')\n    except csv.Error:\n        dialect = csv.excel\n    rows = list(csv.reader(io.StringIO(text), dialect))\n    if not rows:\n        raise ValueError('빈 파일이에요.')\n    header = [h.strip() for h in rows[0]]\n    if len(set(header)) != len(header) or not all(header):\n        raise ValueError('첫 줄은 비어 있지 않고 서로 다른 열 이름이어야 해요.')\n    body = [r for r in rows[1:] if any(cell.strip() for cell in r)]\n    if any(len(r) != len(header) for r in body):\n        raise ValueError('열 개수가 첫 줄과 다른 행이 있어요.')\n    return header, body\n\n\ndef _number(value):\n    try:\n        number = float(value)\n    except ValueError:\n        return None\n    return number if np.isfinite(number) else None\n\n\ndef _blank(cell):\n    return cell.strip().lower() in BLANKS\n\n\ndef _arms(values):\n    \"\"\"K when the values are 0 (control) and 1..K (treatments) with none missing, else 0.\"\"\"\n    levels = sorted(set(values))\n    if len(levels) < 2 or len(levels) - 1 > MAX_TREATMENTS or levels != list(range(len(levels))):\n        return 0\n    return len(levels) - 1\n\n\ndef columns(header, body):\n    sample = body[:2000]\n    out = []\n    for i, name in enumerate(header):\n        filled = [r[i].strip() for r in sample if not _blank(r[i])]\n        values = [_number(cell) for cell in filled]\n        numeric = bool(filled) and all(v is not None for v in values)\n        distinct = list(dict.fromkeys(filled))  # in file order\n        out.append({'name': name, 'numeric': numeric, 'binary': numeric and set(values) <= {0., 1.}, 'arms': _arms(values) if numeric else 0, 'categorical': not numeric and 1 < len(distinct) <= MAX_LEVELS,\n                    'missing': len(sample) - len(filled), 'distinct': len(distinct), 'examples': sorted(distinct) if len(distinct) <= 4 else distinct[:4]})\n    return out\n\n\ndef guess(cols):\n    \"\"\"A first suggestion from column names: the exact name first, then a word inside it (coupon_cost is a cost, is_treated a treatment).\"\"\"\n    def pick(names, test):\n        usable = [c for c in cols if test(c)]\n        return next((c['name'] for c in usable if c['name'].lower() in names),\n                    next((c['name'] for c in usable if set(re.split(r'[^a-z0-9]+', c['name'].lower())) & names), None))\n    cost = pick(COST_NAMES, lambda c: c['numeric'])\n    treatment = pick(TREATMENT_NAMES, lambda c: c['arms'] > 0 and c['name'] != cost)\n    outcome = pick(OUTCOME_NAMES, lambda c: c['numeric'] and c['name'] not in (treatment, cost))\n    features = [c['name'] for c in cols if (c['numeric'] or c['categorical']) and c['name'] not in (treatment, outcome, cost)\n                and c['name'].lower() not in ID_NAMES and c['distinct'] > 1]\n    return {'treatment': treatment, 'outcome': outcome, 'cost': cost, 'features': features}\n\n\ndef detect(header):\n    return 'hillstrom' if HILLSTROM_COLUMNS <= set(header) else None\n\n\ndef inspect(text):\n    \"\"\"Column summary, a suggested mapping and a preview, for the upload screen.\"\"\"\n    header, body = read(text)\n    cols = columns(header, body)\n    adapter = detect(header)\n    return {'rows': len(body), 'header': header, 'columns': cols, 'adapter': adapter, 'preview': body[:8],\n            'mapping': {'adapter': adapter} if adapter else guess(cols), 'minRows': MIN_ROWS}\n\n\ndef _hillstrom(header, body):\n    i = {h: k for k, h in enumerate(header)}\n    get = lambda name: [r[i[name]].strip() for r in body]  # noqa: E731\n    seg, zips, channel = get('segment'), get('zip_code'), get('channel')\n    t = np.asarray([s != 'No E-Mail' for s in seg], dtype=np.int64)\n    y = np.asarray(get('visit'), dtype=np.float64)\n    numeric = {name: np.asarray(get(name), dtype=np.float64) for name in ('recency', 'history', 'mens', 'womens', 'newbie')}\n    X = np.column_stack([numeric['recency'], numeric['history'], numeric['mens'], numeric['womens'], numeric['newbie'],\n                         [z == 'Urban' for z in zips], [z == 'Surburban' for z in zips], [c == 'Phone' for c in channel], [c == 'Web' for c in channel]]).astype(np.float64)\n    features = ['recency', 'history', 'mens', 'womens', 'newbie', 'zip=Urban', 'zip=Suburban', 'channel=Phone', 'channel=Web']\n    return X, t, y, t.astype(np.float64), features, {'adapter': 'hillstrom', 'treatment': 'segment ≠ No E-Mail', 'outcome': 'visit', 'cost': None, 'features': features}\n\n\ndef _required(name, role, cells):\n    values = [_number(cell) for cell in cells]\n    if any(v is None for v in values):\n        raise ValueError(f'{role} 열 {name}에 숫자가 아닌 값이나 빈 값이 있어요.')\n    return np.asarray(values, dtype=np.float64)\n\n\ndef _feature(name, cells):\n    \"\"\"One chosen column as model inputs: numbers stay (blanks become the median), text becomes 0/1 columns per value.\"\"\"\n    filled = [cell.strip() for cell in cells if not _blank(cell)]\n    if not filled:\n        raise ValueError(f'공변량 열 {name}이 비어 있어요.')\n    if all(_number(cell) is not None for cell in filled):\n        column = np.asarray([np.nan if _blank(cell) else float(cell) for cell in cells], dtype=np.float64)\n        gaps = np.isnan(column)\n        column[gaps] = np.median(column[~gaps])\n        return [name], column[:, None], int(gaps.sum())\n    levels = sorted(set(filled))\n    if len(levels) > MAX_LEVELS:\n        raise ValueError(f'문자 열 {name}의 고유값이 {len(levels):,}개예요. {MAX_LEVELS}개까지만 공변량으로 쓸 수 있어요. 제외해 주세요.')\n    if len(levels) == 2:\n        levels = levels[1:]  # one 0/1 column says everything a two-valued column can\n    stripped = [cell.strip() for cell in cells]\n    return [f'{name}={level}' for level in levels], np.asarray([[cell == level for level in levels] for cell in stripped], dtype=np.float64), 0\n\n\ndef fingerprint(body):\n    \"\"\"Identifies the rows themselves, so a file splits the same way under any name, id, line ending or delimiter.\"\"\"\n    digest = hashlib.blake2b(digest_size=8)\n    for row in body:\n        digest.update('\\x1f'.join(cell.strip() for cell in row).encode())\n        digest.update(b'\\x1e')\n    return digest.hexdigest()\n\n\ndef parse(text, mapping=None):\n    header, body = read(text)\n    if len(body) < MIN_ROWS:\n        raise ValueError(f'{MIN_ROWS:,}행 이상이 필요해요. 지금은 {len(body):,}행이에요.')\n    adapter = (mapping or {}).get('adapter') if mapping else detect(header)\n    if adapter == 'hillstrom':\n        X, t, y, cost, features, used = _hillstrom(header, body)\n        filled = {}\n    else:\n        mapping = mapping or guess(columns(header, body))\n        index = {h: k for k, h in enumerate(header)}\n        for role in ('treatment', 'outcome'):\n            if mapping.get(role) not in index:\n                raise ValueError(f'{\"처치\" if role == \"treatment\" else \"결과\"} 열을 선택해 주세요.')\n        chosen = [f for f in mapping.get('features') or [] if f in index]\n        if not chosen:\n            raise ValueError('공변량 열을 하나 이상 선택해 주세요.')\n        cells = lambda column: [r[index[column]] for r in body]  # noqa: E731\n        treatment = _required(mapping['treatment'], '처치', cells(mapping['treatment']))\n        if not _arms(np.unique(treatment).tolist()):\n            raise ValueError(f'처치 열 {mapping[\"treatment\"]}은 0(대조군)과 1, 2처럼 0부터 이어지는 정수여야 해요. 처치는 {MAX_TREATMENTS}종류까지 쓸 수 있어요.')\n        t, y = treatment.astype(np.int64), _required(mapping['outcome'], '결과', cells(mapping['outcome']))\n        cost = _required(mapping['cost'], '비용', cells(mapping['cost'])) if mapping.get('cost') else (t > 0).astype(np.float64)  # no cost column: one unit per treated row\n        features, parts, filled = [], [], {}\n        for column in chosen:\n            names, part, gaps = _feature(column, cells(column))\n            features += names\n            parts.append(part)\n            if gaps:\n                filled[column] = gaps\n        X = np.hstack(parts)\n        used = {'adapter': None, 'treatment': mapping['treatment'], 'outcome': mapping['outcome'], 'cost': mapping.get('cost'), 'features': chosen}\n    if t.min() == t.max():\n        raise ValueError('처치군과 대조군이 모두 필요해요.')\n    return SimpleNamespace(fingerprint=fingerprint(body), X=X, t=t, y=y, cost=cost, features=features, mapping=used, filled=filled)\n\n\ndef quality(X, t, y, cost, features, filled=None):\n    \"\"\"Validity checks for an uploaded experiment log. Passing does not prove the assignment was random.\"\"\"\n    treated, checks = t > 0, []\n    share = float(treated.mean())\n    K = int(t.max())\n    shares = [float((t == k).mean()) for k in range(1, K + 1)]\n    balanced_share = .05 <= share <= .95 and min(shares) >= .02\n    detail = f' (T=1~{K}: ' + ', '.join(f'{s:.0%}' for s in shares) + ')' if K > 1 else ''\n    checks.append({'id': 'share', 'title': '처치 비율', 'level': 'ok' if balanced_share else 'warn',\n                   'text': f'처치군 {share:.0%}{detail}, 대조군 {1 - share:.0%}예요.' + ('' if balanced_share else ' 한쪽 표본이 너무 적으면 ATE 추정이 불안정해요.')})\n    a, b = X[treated], X[~treated]\n    spread = np.sqrt((a.var(0) + b.var(0)) / 2)\n    gap = np.divide(np.abs(a.mean(0) - b.mean(0)), spread, out=np.zeros(X.shape[1]), where=spread > 0)\n    worst = np.argsort(-gap)[:3]\n    top = float(gap[worst[0]])\n    if top > .1:\n        names = ', '.join(f'{features[j]} {gap[j]:.2f}' for j in worst if gap[j] > .1)\n        checks.append({'id': 'balance', 'title': '공변량 균형', 'level': 'bad' if top > .25 else 'warn',\n                       'text': f'처치군과 대조군의 공변량 분포가 달라요 (SMD: {names}). 무작위 배정이 아니면 ATE가 편향될 수 있어요.'})\n    else:\n        checks.append({'id': 'balance', 'title': '공변량 균형', 'level': 'ok',\n                       'text': f'처치군과 대조군의 공변량 차이가 작아요 (최대 SMD: {features[worst[0]]} {top:.2f}). 무작위 배정과 어긋나는 신호는 없지만, 무작위 배정을 증명하지는 않아요.'})\n    delta = float(cost[treated].mean() - cost[~treated].mean())\n    checks.append({'id': 'cost', 'title': '증분 비용', 'level': 'ok' if delta > 0 else 'bad',\n                   'text': f'처치군의 평균 비용이 대조군보다 {delta:,.2f} 커요 (ATEᶜ).' if delta > 0 else f'ATEᶜ가 {delta:,.2f}라서 비용 효율을 계산할 수 없어요. 비용 열을 확인해 주세요.'})\n    if np.ptp(y) == 0:\n        checks.append({'id': 'outcome', 'title': '결과', 'level': 'bad', 'text': '결과 값이 모두 같아 ATE를 추정할 수 없어요.'})\n    per_cycle = len(t) // 8\n    checks.append({'id': 'size', 'title': '표본 크기', 'level': 'ok' if per_cycle >= 2000 else 'warn',\n                   'text': f'8사이클 기준 사이클당 {min(per_cycle, 20000):,}행이에요.' + ('' if per_cycle >= 2000 else ' 표본이 작을수록 관측값의 변동이 커요.')})\n    if filled:\n        total = sum(filled.values())\n        checks.append({'id': 'blanks', 'title': '결측값', 'level': 'ok', 'text': f'공변량 결측값 {total:,}개를 열별 중앙값으로 대체했어요 ({\", \".join(filled)}).'})\n    return checks\n\n\ndef profile(X, t, y, cost, features, tau_r=None, tau_c=None, filled=None):\n    treated = t > 0\n    out = {'checks': quality(X, t, y, cost, features, filled), 'rows': int(len(t)), 'treatments': int(t.max()), 'treatedShare': float(treated.mean()), 'outcomeT': float(y[treated].mean()), 'outcomeC': float(y[~treated].mean()),\n           'costT': float(cost[treated].mean()), 'costC': float(cost[~treated].mean()), 'features': [], 'preview': {'columns': list(features) + ['t', 'y', 'cost'],\n           'rows': [[round(float(v), 3) for v in X[i]] + [int(t[i]), round(float(y[i]), 3), round(float(cost[i]), 3)] for i in range(min(8, len(t)))]}}\n    out['ate'] = out['outcomeT'] - out['outcomeC']\n    for j, name in enumerate(features):\n        col = X[:, j]\n        lo, hi = float(col.min()), float(col.max())\n        out['features'].append({'name': name, 'min': lo, 'max': hi, 'mean': float(col.mean()),\n                                'hist': np.histogram(col, bins=16, range=(lo, hi if hi > lo else lo + 1))[0].tolist()})\n    if tau_r is not None:\n        out['truth'] = {'tauR': float(tau_r.mean()), 'tauC': float(tau_c.mean())}\n    return out\n\n\ndef profile_synthetic(dataset_id, seed=42):\n    pop = SyntheticScenario(synthetic_preset(dataset_id), seed=seed).cohort(1)\n    idx = np.arange(len(pop))\n    t = pop.assign(idx)\n    y, cost = pop.outcome(idx, t)\n    return profile(pop.X, t, y, cost, SyntheticScenario.features, pop.tau_r, pop.tau_c)\n\n\ndef fetch(dataset_id, cache=Path.home() / '.cache' / 'upliftlab' / 'datasets'):\n    \"\"\"Local edition only: download a public dataset from its source once and keep it in the user's cache.\"\"\"\n    meta = next((d for d in PUBLIC if d['id'] == dataset_id), None)\n    if meta is None:\n        raise ValueError(f'내려받을 수 없는 데이터예요: {dataset_id}')\n    path = cache / (dataset_id.split('/')[-1] + '.csv')\n    if not path.exists():\n        cache.mkdir(parents=True, exist_ok=True)\n        with urllib.request.urlopen(meta['download'], timeout=60) as response:\n            data = response.read()\n        path.write_bytes(data)\n    return path.read_text(encoding='utf-8', errors='replace')\n\n\nSAMPLE_NAME = 'upliftlab-예시-쿠폰실험.csv'\nSAMPLE_COLUMNS = ['user_id', 'visit_freq', 'days_since_last', 'price_sensitivity', 'avg_order_value', 'treatment', 'retained', 'coupon_cost']\n\n\ndef sample_csv(rows=40000, seed=7):\n    \"\"\"A randomized coupon experiment drawn from the base market and written like a real log, for trying the upload flow.\n\n    Half the users got the coupon at random. Covariates are in everyday units (visits a month, days since the last visit,\n    order value in won) and the cost is the redeemed coupon amount in won, so the file reads like an export from a CRM tool.\n    \"\"\"\n    scenario, lines, made, cycle = SyntheticScenario('base', seed=seed, pool=20000), [','.join(SAMPLE_COLUMNS)], 0, 1\n    while made < rows:\n        pop = scenario.cohort(cycle)\n        idx = np.arange(min(len(pop), rows - made))\n        t = pop.assign(idx)\n        y, cost = pop.outcome(idx, t)\n        for i, (f, l, p, c) in enumerate(pop.X[idx]):\n            lines.append(f'u{made + i + 1:06d},{round(f * 20)},{round(l * 90)},{p:.2f},{round((5000 + c * 45000) / 100) * 100},{int(t[i])},{int(y[i])},{round(cost[i] * 1000)}')\n        made, cycle = made + len(idx), cycle + 1\n    return '\\n'.join(lines) + '\\n'\n","upliftlab/metrics.py":"\"\"\"Group statistics, cost curves, AUCC, Qini and uplift@k, used by the arena to score every algorithm the same way.\"\"\"\nimport numpy as np\n\n\ndef cell(t, yr, yc):\n    t = np.asarray(t) > 0\n    nT, nC = int(t.sum()), int((~t).sum())\n    out = {'n': nT + nC, 'nT': nT, 'nC': nC, 'retainT': None, 'retainC': None, 'ateR': None, 'ateC': None, 'R': None,\n           'spend': float(yc.sum()), 'redeemed': int((yc[t] > 0).sum())}\n    if nT and nC:\n        out.update(retainT=float(yr[t].mean()), retainC=float(yr[~t].mean()), ateR=float(yr[t].mean() - yr[~t].mean()), ateC=float(yc[t].mean() - yc[~t].mean()))\n        out['R'] = out['ateR'] / out['ateC'] if out['ateC'] else None\n    return out\n\n\ndef cost_curve(score, t, yr, yc, points=20, tau_r=None, tau_c=None):\n    \"\"\"Rank by score; for each top fraction S, n₁(S)·(Ȳ_T − Ȳ_C) for value and cost. With tau_* it sums true effects.\"\"\"\n    order = np.argsort(-np.asarray(score, dtype=np.float64), kind='stable')\n    n = len(order)\n    idx = np.round(np.arange(1, points + 1) * n / points).astype(int) - 1\n    if tau_r is not None:\n        value, cost = np.cumsum(tau_r[order])[idx], np.cumsum(tau_c[order])[idx]\n    else:\n        T = (np.asarray(t)[order] > 0).astype(np.float64)\n        nT, nC = np.cumsum(T)[idx], np.cumsum(1 - T)[idx]\n        rT, rC = np.cumsum(yr[order] * T)[idx], np.cumsum(yr[order] * (1 - T))[idx]\n        cT, cC = np.cumsum(yc[order] * T)[idx], np.cumsum(yc[order] * (1 - T))[idx]\n        ok = (nT > 0) & (nC > 0)\n        with np.errstate(divide='ignore', invalid='ignore'):\n            value = np.where(ok, nT * (rT / nT - rC / nC), 0.)\n            cost = np.where(ok, nT * (cT / nT - cC / nC), 0.)\n    return [{'f': 0., 'cost': 0., 'value': 0.}] + [{'f': (i + 1) / points, 'cost': float(c), 'value': float(v)} for i, (c, v) in enumerate(zip(cost, value))]\n\n\ndef aucc(points):\n    \"\"\"Area under the curve normalized by its maximum cost and value. Random ranking ≈ 0.5, which is not a lower bound.\"\"\"\n    X, Y = max(p['cost'] for p in points), max(p['value'] for p in points)\n    if not (X > 0 and Y > 0):\n        return None\n    return float(sum((b['cost'] - a['cost']) / X * (b['value'] + a['value']) / Y / 2 for a, b in zip(points, points[1:])))\n\n\ndef qini(points):\n    \"\"\"Area between the Qini curve and the random line, as a share of the incremental outcome of treating everyone.\n\n    The Qini curve is the incremental outcome n₁(S)·(Ȳ_T − Ȳ_C) against the share of users targeted, which is the value\n    column of the cost curve. Random ranking ≈ 0; a positive value means the top of the ranking holds more of the effect.\n    \"\"\"\n    total = points[-1]['value']\n    if not total:\n        return None\n    area = sum((b['f'] - a['f']) * (a['value'] + b['value']) / 2 for a, b in zip(points, points[1:]))\n    return float((area - total / 2) / abs(total))\n\n\ndef uplift_at(score, k, t=None, yr=None, tau_r=None):\n    \"\"\"Average treatment effect among the top k share of users by score.\"\"\"\n    order = np.argsort(-np.asarray(score, dtype=np.float64), kind='stable')\n    top = order[:max(1, int(round(len(order) * k)))]\n    if tau_r is not None:\n        return float(np.mean(tau_r[top]))\n    treated = np.asarray(t)[top] > 0\n    if not treated.any() or treated.all():\n        return None\n    return float(yr[top][treated].mean() - yr[top][~treated].mean())\n","upliftlab/scenario.py":"\"\"\"Where each cycle's candidates come from: a synthetic market with known effects, or a logged randomized experiment.\n\n`t` is 0 for control and 1..K for the K treatments. Most datasets have one treatment, so K = 1 and t is the usual 0/1.\n\"\"\"\nimport hashlib\n\nimport numpy as np\n\nREDEEM = 0.85\n\n\ndef seed_of(*parts):\n    return int.from_bytes(hashlib.blake2b('|'.join(map(str, parts)).encode(), digest_size=8).digest(), 'little')\n\n\nclass Population:\n    \"\"\"One cycle's candidates. `assign` and `outcome` hide whether outcomes are simulated or replayed.\"\"\"\n\n    def __init__(self, ids, X, u_explore, u_split, assign, outcome, tau_r=None, tau_c=None, explore_arm=None, treatments=1):\n        self.ids, self.X, self.u_explore, self.u_split = ids, X, u_explore, u_split\n        self.assign, self.outcome, self.tau_r, self.tau_c = assign, outcome, tau_r, tau_c\n        self.explore_arm, self.treatments = explore_arm or (lambda idx: np.ones(len(idx), dtype=np.int64)), treatments\n\n    def __len__(self):\n        return len(self.X)\n\n    def truth(self, idx, arm):\n        \"\"\"True incremental outcome and cost of giving treatment `arm` to the rows `idx`.\"\"\"\n        if self.tau_r.ndim == 1:\n            return self.tau_r[idx], self.tau_c[idx]\n        return self.tau_r[idx, arm - 1], self.tau_c[idx, arm - 1]\n\n\nclass SyntheticScenario:\n    \"\"\"Users who return anyway cost a lot and gain little; lapsed users respond; high spenders respond but cost more.\n\n    Every user has all potential outcomes, so the true effect of any selection is known exactly.\n    \"\"\"\n    kind = 'synthetic'\n    truth = True\n    propensity = .5\n    features = ['최근 이용 빈도', '이용 공백', '가격 민감도', '평균 결제액']\n    PRESETS = {'base': (0, 0, 0, 0), 'loyal': (.16, -.08, 0, 0), 'premium': (0, .04, .12, .18), 'tiers': (0, 0, 0, 0)}\n    # Treatment levels of a market: how much a reward costs relative to the base reward, and how much of the base effect it buys.\n    # The effect saturates, so the largest reward is rarely the most cost-effective one.\n    LEVELS = {'tiers': {'cost': (.5, 1., 1.5), 'effect': (.55, 1., 1.3), 'labels': ['보상 ×0.5', '보상 ×1', '보상 ×1.5']}}\n    SINGLE = {'cost': (1.,), 'effect': (1.,), 'labels': ['보상 지급']}\n\n    def __init__(self, preset='base', seed=42, pool=20000, cycles=8):\n        if preset not in self.PRESETS:\n            raise ValueError(f'알 수 없는 합성 시나리오예요: {preset}')\n        self.preset, self.seed, self.pool, self.cycles = preset, seed, int(pool), int(cycles)\n        self.levels = self.LEVELS.get(preset, self.SINGLE)\n        self.treatments = len(self.levels['cost'])\n        self.labels = self.levels['labels']\n        self.propensities = np.full(self.treatments, 1 / (self.treatments + 1))  # P(T = k | T in {0, k}): half the users are control\n\n    @staticmethod\n    def potential(X):\n        f, l, p, c = X.T\n        p0 = 1 / (1 + np.exp(-(-.55 + 2.4 * f - 1.9 * l + .25 * c)))\n        p1 = np.clip(p0 + .02 + .22 * l * (1 - .65 * f) + .08 * p + .07 * c, 0, .97)\n        value = .8 + 3.6 * c\n        return p0, p1, value\n\n    def cohort(self, cycle):\n        rng = np.random.default_rng(seed_of(self.seed, 'cohort', self.preset, cycle))\n        n, shift, K = self.pool, np.asarray(self.PRESETS[self.preset]), self.treatments\n        X = np.clip((rng.random((n, 4)) + rng.random((n, 4))) / 2 + shift + (rng.random((n, 4)) - .5) * .24, 0, 1)\n        p0, p1, value = self.potential(X)\n        u_explore, u_t, u_y, u_redeem, u_split = rng.random((5, n))\n        P = np.column_stack([p0] + [p1 if r == 1 else np.clip(p0 + (p1 - p0) * r, 0, .97) for r in self.levels['effect']])  # (n, K + 1)\n        unit = value[:, None] * np.asarray(self.levels['cost'])  # (n, K)\n        arms = np.ones(n, dtype=np.int64)\n        if K > 1:\n            arms = 1 + np.floor(np.random.default_rng(seed_of(self.seed, 'arm', self.preset, cycle)).random(n) * K).astype(np.int64)\n\n        def explore_arm(idx):\n            return arms[idx]\n\n        def assign(idx, arm=None):\n            \"\"\"Half the rows stay control. The rest get `arm`, or their random Explore treatment when none is given.\"\"\"\n            return (u_t[idx] < .5).astype(np.int64) * (arms[idx] if arm is None else np.asarray(arm, dtype=np.int64))\n\n        def outcome(idx, t):\n            yr = (u_y[idx] < P[idx, t]).astype(np.float64)\n            return yr, (t > 0) * yr * (u_redeem[idx] < REDEEM) * unit[idx, np.maximum(t, 1) - 1]\n\n        ids = [f'c{cycle}-{i + 1:05d}' for i in range(n)]\n        tau_r, tau_c = P[:, 1:] - p0[:, None], P[:, 1:] * REDEEM * unit\n        if K == 1:\n            tau_r, tau_c = tau_r[:, 0], tau_c[:, 0]\n        return Population(ids, X, u_explore, u_split, assign, outcome, tau_r=tau_r, tau_c=tau_c, explore_arm=explore_arm, treatments=K)\n\n\nclass ReplayScenario:\n    \"\"\"A logged randomized experiment: rows are split into disjoint per-cycle pools and their logged T is reused.\n\n    Any selection's effect can still be estimated because T was random inside every subset; there is no ground truth.\n    With several treatments only rows whose logged T is control or the treatment the algorithm chose can be measured.\n    The split depends only on the file's rows and the seed, so the same file and seed reproduce the same result.\n    \"\"\"\n    kind = 'replay'\n    truth = False\n\n    def __init__(self, data, seed=42, cycles=8, pool=20000):\n        n = len(data.t)\n        self.data, self.seed = data, seed\n        self.cycles = int(max(1, min(cycles, n // 400)))\n        self.pool = int(min(pool, n // self.cycles))\n        if self.pool < 200:\n            raise ValueError('행이 너무 적어요. 사이클마다 최소 200행이 필요해요.')\n        self.order = np.random.default_rng(seed_of(seed, 'replay', data.fingerprint)).permutation(n)\n        self.treatments = int(data.t.max())\n        self.propensity = float((data.t > 0).mean())\n        self.propensities = np.array([float((data.t == k).sum() / ((data.t == k) | (data.t == 0)).sum()) for k in range(1, self.treatments + 1)])\n        self.labels = [f'T={k}' for k in range(1, self.treatments + 1)] if self.treatments > 1 else ['처치']\n        self.features = data.features\n\n    def cohort(self, cycle):\n        d, rows = self.data, self.order[(cycle - 1) * self.pool:cycle * self.pool]\n        u_explore, u_split = np.random.default_rng(seed_of(self.seed, 'replay', d.fingerprint, cycle)).random((2, len(rows)))\n        return Population([f'row{r + 1}' for r in rows], d.X[rows], u_explore, u_split,\n                          lambda idx, arm=None: d.t[rows[idx]], lambda idx, t: (d.y[rows[idx]], d.cost[rows[idx]]),\n                          explore_arm=lambda idx: np.maximum(d.t[rows[idx]], 1), treatments=self.treatments)\n","upliftlab/templates/start_lightgbm.py":"\"\"\"트리 모델로 공변량의 비선형 관계를 학습하는 T-Learner예요. 모델 4개가 각자 validation으로 조기 종료하고, 성과 − λ·비용 순으로 정렬해요.\n\n모델 네 개 = 성과·비용 × 처치군·대조군. PARAMS를 바꿔 트리 크기와 학습률을 조정해요.\n\"\"\"\nimport lightgbm as lgb\nimport numpy as np\n\nNAME = 'LightGBM T-Learner'\nCOST_WEIGHT = 0.4  # λ: 표준편차로 정규화한 비용의 가중치. 비용의 단위와 무관해요.\n# 수천 행에서는 스레드 하나가 가장 빨라요(n_jobs=1). 데이터가 크면 늘려 보세요.\nPARAMS = dict(n_estimators=400, learning_rate=0.05, num_leaves=15, min_child_samples=50, subsample=0.8, subsample_freq=1, n_jobs=1, verbose=-1)\n\n\nclass Model:\n    def fit(self, train, validation, context):\n        self.models = {}\n        self.scale = (train.y.std() or 1) / (train.cost.std() or 1)\n        self.treatments = train.treatments\n        arms = [*range(1, train.treatments + 1), 0]  # t = 1..K는 처치, 0은 대조군이에요\n        for target in ('y', 'cost'):\n            for arm in arms:\n                rows, val = train.t == arm, validation.t == arm\n                model = lgb.LGBMRegressor(**PARAMS, random_state=context.model_seed)\n                model.fit(train.X[rows], getattr(train, target)[rows],\n                          eval_set=[(validation.X[val], getattr(validation, target)[val])],\n                          callbacks=[lgb.early_stopping(30, verbose=False)])\n                self.models[target, arm] = model\n                context.report(step=len(self.models), total=2 * len(arms), trees=model.best_iteration_)\n\n    def uplift(self, target, X, arm):\n        return self.models[target, arm].predict(X) - self.models[target, 0].predict(X)\n\n    def predict(self, X):\n        return np.column_stack([self.uplift('y', X, arm) - COST_WEIGHT * self.scale * self.uplift('cost', X, arm) for arm in range(1, self.treatments + 1)])\n","upliftlab/templates/start_pytorch.py":"\"\"\"PyTorch로 '증분 비용 ÷ 증분 성과'를 직접 줄이는 순위 모델이에요. 기울기는 autograd가 계산하고, GPU가 있으면 GPU에서 돌아요.\n\n브라우저에는 PyTorch가 없어서 로컬(python -m upliftlab serve)에서 실행해요. context.device가 'cuda:0'이면 GPU를 써요.\n처치가 K종류면 네트워크 출력이 K개이고, 사용자마다 점수가 가장 큰 처치를 골라요.\n\"\"\"\nimport torch\n\nNAME = 'PyTorch 순위 모델'\nEPOCHS = 300\nHIDDEN = 16\nLEARNING_RATE = 0.01\n\n\ndef lift(score, t, value, log_share):\n    \"\"\"score를 softmax한 정책으로 고른 (사용자, 처치)의 증분 value.\n\n    처치군은 기록된 처치의 점수로, 대조군은 모든 처치의 점수로 가중해요. 한 softmax 안에서 처치끼리 경쟁하므로\n    처치 사이의 점수를 비교할 수 있어요. log_share는 처치별 표본 크기의 차이를 보정해요.\n    \"\"\"\n    treated, control = t > 0, t == 0\n    arm = t[treated] - 1\n    p_t = torch.softmax(score[treated, arm] - log_share[arm], 0)\n    p_c = torch.softmax(score[control].flatten(), 0)\n    return (p_t * value[treated]).sum() - (p_c * value[control].repeat_interleave(score.shape[1])).sum()\n\n\nclass Model:\n    def fit(self, train, validation, context):\n        torch.manual_seed(context.model_seed)\n        self.device = torch.device(context.device if torch.cuda.is_available() else 'cpu')\n        self.mean, self.std = train.X.mean(0), train.X.std(0) + 1e-9\n        X, t = self.inputs(train.X), torch.as_tensor(train.t, device=self.device)\n        y, cost = (torch.as_tensor(v, dtype=torch.float32, device=self.device) for v in (train.y, train.cost))\n        log_share = torch.stack([(t == k).float().mean().log() for k in range(1, train.treatments + 1)])\n        log_share = log_share - log_share.mean()\n        self.net = torch.nn.Sequential(torch.nn.Linear(X.shape[1], HIDDEN), torch.nn.ReLU(), torch.nn.Linear(HIDDEN, train.treatments), torch.nn.Tanh()).to(self.device)\n        optimizer = torch.optim.Adam(self.net.parameters(), lr=LEARNING_RATE)\n        for epoch in range(1, EPOCHS + 1):\n            score = self.net(X)\n            loss = lift(score, t, cost, log_share) / lift(score, t, y, log_share).clamp_min(1e-4)\n            optimizer.zero_grad()\n            loss.backward()\n            optimizer.step()\n            if epoch == 1 or epoch % 10 == 0:\n                context.report(step=epoch, total=EPOCHS, loss=loss.item())\n\n    def inputs(self, X):\n        return torch.as_tensor((X - self.mean) / self.std, dtype=torch.float32, device=self.device)\n\n    def predict(self, X):\n        with torch.no_grad():\n            return self.net(self.inputs(X)).cpu().numpy()\n","upliftlab/templates/start_sklearn.py":"\"\"\"가장 가벼운 시작 템플릿이에요. scikit-learn Ridge T-Learner로 증분 성과와 증분 비용을 추정하고, 성과 − λ·비용 순으로 정렬해요.\n\nregressor()를 다른 scikit-learn 모델로 바꾸거나 COST_WEIGHT를 조정해 보세요.\n\"\"\"\nimport numpy as np\nfrom sklearn.linear_model import Ridge\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nNAME = 'scikit-learn T-Learner'\nCOST_WEIGHT = 0.4  # λ: 표준편차로 정규화한 비용의 가중치. 비용의 단위와 무관해요.\n\n\ndef regressor():\n    # 예: from sklearn.ensemble import HistGradientBoostingRegressor → HistGradientBoostingRegressor(max_depth=3)\n    return make_pipeline(StandardScaler(), Ridge(alpha=1.0))\n\n\nclass TLearner:\n    \"\"\"target의 증분 효과 τ̂(x) = μ̂₁(x) − μ̂₀(x). arm은 비교할 처치 번호예요.\"\"\"\n\n    def fit(self, X, t, target, arm=1):\n        self.mu1 = regressor().fit(X[t == arm], target[t == arm])\n        self.mu0 = regressor().fit(X[t == 0], target[t == 0])\n        return self\n\n    def predict(self, X):\n        return self.mu1.predict(X) - self.mu0.predict(X)\n\n\nclass Model:\n    def fit(self, train, validation, context):\n        # train.X (n×d 배열) · t (0/1) · y (결과) · cost (비용) · propensity · features (열 이름)\n        # pandas가 편하면 pd.DataFrame(train.X, columns=train.features)로 바꿔 써요.\n        # 처치가 여러 종류면 train.treatments가 그 수예요(t = 1..K). 처치마다 모델을 따로 학습해요.\n        arms = range(1, train.treatments + 1)\n        self.gain = [TLearner().fit(train.X, train.t, train.y, arm) for arm in arms]\n        self.cost = [TLearner().fit(train.X, train.t, train.cost, arm) for arm in arms]\n        self.scale = (train.y.std() or 1) / (train.cost.std() or 1)\n\n    def predict(self, X):\n        # 점수가 높을수록 먼저 처치해요. 처치가 여러 종류면 (행 수, 처치 수) 배열을 반환하고, 사용자마다 점수가 가장 큰 처치를 줘요.\n        return np.column_stack([gain.predict(X) - COST_WEIGHT * self.scale * cost.predict(X) for gain, cost in zip(self.gain, self.cost)])\n"};
